window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q07"]=window.__LIBQ["the-gioi-hoan-my"]["q07"]||{};window.__LIBQ["the-gioi-hoan-my"]["q07"]["cotTruyen"]=[{"chuong":601,"tieuDe":"Sau Khi Chết","tomTat":"Thạch thôn an táng Thạch Hạo trên ngọn núi thấp, còn Thạch Vân Phong và những người từng nuôi hắn lớn đau đớn tưởng niệm hành trình từ đứa trẻ mồ côi đến Nhân hoàng. Thạch Quốc tổ chức quốc tang tại Thạch Đô, thu hút quốc chủ, giáo chủ, kỳ tài thượng giới và hơn mười vị Tôn giả từ nhiều đại vực đến cúng viếng. Tại thượng giới, Ma Quỳ Viên, Minh Thổ và Thiên Quốc tức giận khi biết toàn bộ lực lượng vượt giới đã bị tiêu diệt, trong khi các học viện kinh ngạc trước chiến tích của thiếu niên hạ giới. Pháp tắc thiên đạo trở nên nghiêm khắc hơn, khiến đường từ thượng giới xuống hạ giới bị cắt hoàn toàn và con đường đi lên cũng khó khăn gấp bội. Ba tháng sau, tin Thạch Hạo tặng Chí Tôn cốt cho Tần Hạo bị tiết lộ; Tần Hạo đã dung hợp thành công, sở hữu hai khối bảo cốt và trở thành đối tượng được các thiên tài thượng giới đến Bất Lão Sơn kết giao. Sau lễ một trăm ngày, Thạch Lâm Hổ phát hiện linh khí quanh mộ Thạch Hạo dường như nồng đậm hơn trước, nhưng chưa ai biết nguyên nhân."},{"chuong":602,"tieuDe":"Sinh Cơ Bất Tuyệt","tomTat":"Hơn ba tháng sau khi Thạch Hạo được an táng, bạn bè thuở nhỏ vẫn thường mang rượu lên mộ tưởng niệm, còn Thạch Vân Phong suy sụp vì mất người cháu do chính tay mình nuôi lớn. Thạch Tử Lăng quyết lên thượng giới khổ tu và báo thù, đưa Tần Hạo đi qua thiên lộ, trong khi Tần Di Ninh ban đầu lựa chọn ở lại hạ giới. Gần một năm sau, Bất Lão Sơn dùng tin tức bị phóng đại về chồng và con thứ để buộc Tần Di Ninh trở về thượng giới giữa lúc đường liên lạc hai giới gần như đoạn tuyệt. Tại thượng giới, Tần Hạo công khai hai khối Chí Tôn cốt, liên tiếp đánh bại năm thiên kiêu cùng cảnh giới và được linh thân của Bất Lão Thiên Tôn bảo vệ. Quanh mộ Thạch Hạo, cỏ lạ do Ngũ Sắc Tước gieo ngày càng dày, khiến linh khí trên ngọn núi thấp tăng mạnh. Khi rễ cỏ đồng loạt phát sáng, Thạch Vân Phong cảm nhận sinh cơ thức tỉnh, còn Bóng Lông dùng Viên Trùng Đồng xác nhận sức sống phát ra từ chính quan tài. Cảm giác luân hồi dưới mộ cùng suy đoán của Tiểu Hồng cho thấy lĩnh ngộ luân hồi trước đây của Thạch Hạo có thể là nguyên nhân khiến hắn chưa thực sự tuyệt diệt."},{"chuong":603,"tieuDe":"Cỏ Bất Hủ","tomTat":"Bóng Lông dùng Viên Trùng Đồng quan sát dưới mộ Thạch Hạo, phát hiện những bộ rễ trắng bạc quấn quanh quan tài thành kén và phát ra dao động luân hồi. Nhị Mãnh tự ý dùng thần thức thăm dò nên suýt chìm trong cảm giác trải qua trăm nghìn đời, buộc Bóng Lông phải quát tỉnh. Sau khi kiểm tra và đối chiếu, Bóng Lông cùng Tiểu Hồng xác định kỳ thảo quanh mộ là cỏ Bất Hủ, được lai tạo từ cỏ Hoàn Hồn và cỏ Luân Hồi, có thể giữ thân thể không mục nát và thần thức không tiêu tán. Lớp đất đen trắng dưới vùng cỏ khiến họ suy đoán Ngũ Sắc Tước đã mang cả cỏ lẫn đất từ một cổ địa đặc biệt tới cứu Thạch Hạo. Thạch thôn lập tức đóng tế đàn, đoạn tuyệt liên hệ với bên ngoài và cử người canh giữ ngôi mộ để bảo vệ bí mật. Ngũ Sắc Tước nhiều lần trở lại cảm ứng trên mộ, được dân làng quỳ lạy cảm tạ. Hai tháng sau, mộ đất, kén rễ và quan tài đồng loạt nứt vỡ, để lộ thân thể Thạch Hạo hồng nhuận với phù văn cùng thần huy lưu chuyển. Khi luồng khí trắng xuất hiện từ mũi hắn, dân làng xác nhận Thạch Hạo đã bắt đầu hô hấp trở lại."},{"chuong":604,"tieuDe":"Phục Sinh","tomTat":"Sau hơn một năm nằm trong quan tài, Thạch Hạo bắt đầu hô hấp trở lại, tim đập mạnh và tỏa ra sinh cơ khiến người Thạch thôn vui mừng khôn xiết. Tinh hoa từ Bất Hủ thảo, Bất lão tuyền, Rượu Côn Bằng, Ngân đào, Hoàng kim dịch và những vật chất thần tính từng dùng cứu hắn dần phát huy tác dụng, sửa chữa gân mạch, xương cốt và huyết nhục. Bóng Lông cùng Tiểu Hồng phát hiện Chí Tôn huyết đang lưu chuyển khắp cơ thể, vừa tẩm bổ thương thế vừa thiêu đốt phù văn nguyền rủa gỉ đồng. Nguyền rủa tuy tiêu hao chân huyết nhưng cũng trở thành đường dẫn khiến dòng máu này đi tới từng nơi cần gột rửa, tạo nên cục diện hung hiểm đi cùng tạo hóa. Mọi người kỳ vọng Chí Tôn huyết có thể tái sinh mạnh hơn sau khi cạn kiệt, dù Chí Tôn cốt đã mất và thương thế của Thạch Hạo chưa hoàn toàn khép lại. Sau nhiều ngày khí thế sinh mệnh tăng cao, ánh sáng từ lòng đất làm mộ và quan tài vỡ nát, còn Thạch Hạo đột ngột mở mắt."},{"chuong":605,"tieuDe":"Ghi Nhớ Vào Thân Thể","tomTat":"Sau hơn một năm nằm dưới mộ chống chọi nguyền rủa, Thạch Hạo phát sinh dị biến khiến quan tài hóa tro, ngôi mộ cùng ngọn núi thấp rung chuyển và nứt vỡ. Bóng Lông và Tiểu Hồng bảo vệ dân Thạch thôn, đồng thời nhận ra thân thể hắn đã nhiều lần bị phá hủy rồi tái tạo dưới tác động của nguyền rủa, phù văn gỉ đồng và Chí Tôn huyết. Thạch Hạo mở mắt trong trạng thái luân hồi, tạm thời mất phương hướng, nhưng máu thịt và xương cốt đã ghi nhớ toàn bộ phù văn cùng bảo thuật vốn thuộc Chí Tôn cốt. Chùm Chí Tôn huyết cuối cùng bị kiếm khí trong cơ thể hắn chém tan, cháy lên gột rửa toàn thân rồi đẩy tàn dư tử phù của Tiên điện ra ngoài. Nhờ đạo âm của Bóng Lông và Tiểu Hồng, Thạch Hạo hoàn toàn tỉnh táo, nhận ra người thân và bước khỏi mộ. Hắn xác nhận bảo thuật vẫn còn nguyên, khiến dân làng vui mừng đoàn tụ, trong khi Bóng Lông kỳ vọng Chí Tôn huyết sẽ tái sinh và giúp bảo thuật tiếp tục niết bàn."},{"chuong":606,"tieuDe":"Vui Mừng","tomTat":"Thạch Vân Phong tận tay xác nhận Thạch Hạo đã sống lại, khiến nỗi đau kéo dài hơn một năm của ông và toàn thể Thạch thôn chuyển thành niềm vui vỡ òa. Dân làng mở tiệc suốt đêm bên hồ, còn những người thân quen lần lượt tới khóc, mời rượu và ôn lại chuyện cũ với Thạch Hạo. Qua lời mọi người, cậu biết cha mẹ đã đi đâu, biết ân cứu mạng của Ngũ Sắc Tước và biết Thanh Lân Ưng cùng nhiều đồng bạn vẫn miệt mài tìm Thần tàng Chí tôn cùng cỏ Hoàn Hồn để cứu mình. Sau khi kiểm tra bình ngọc, Thạch Hạo xác nhận nguyền rủa đã bị diệt trừ, chỉ còn xương gãy và các vết thương thể xác, rồi nghe lời Bóng Lông mà quyết định dưỡng thương tại hạ giới trước. Trước nỗi lo phải chia lìa lâu dài, cậu hứa sẽ tìm cách quay lại hạ giới trong vài chục năm. Thạch Hạo còn dự định dùng cổ đan phương của Thạch thôn luyện Kim đan giúp tộc nhân đột phá và kéo dài tuổi thọ, dù việc này cần hơn một trăm loại linh dược hiếm. Để vừa thu thập dược liệu vừa báo thù cho những sinh linh bị huyết tế, cậu quyết định thanh toán các đại giáo bất hủ liên quan, chém một số Tôn giả và trực tiếp đến thánh địa của họ."},{"chuong":607,"tieuDe":"Không Nỡ","tomTat":"Trong đêm đoàn tụ tại Thạch thôn, mọi người phẫn nộ trước cuộc huyết tế sinh linh hạ giới và liên tục căn dặn Thạch Hạo phải thận trọng khi tới thượng giới. Thạch Phi Giao cùng Thanh Phong cho biết thiên lộ đã đứt, khiến hai giới không thể qua lại và các đại giáo bất hủ cũng không truyền được tin lên trên, nhưng Thạch Hạo vẫn tin sẽ tìm thấy con đường khác. Những ngày sau đó, nó vui sống bên tộc nhân, dẫn trẻ nhỏ thám hiểm Đại hoang và mang về linh dược, Ngân Linh thu, ba ba vàng cùng nhiều linh vật để gây dựng nền tảng lâu dài cho thôn. Thương thế của Thạch Hạo cuối cùng hoàn toàn lành hẳn, tinh khí sung mãn và chiến lực còn mạnh hơn trước, khiến nó quyết định đã đến lúc ra ngoài. Tại thủ phủ Thạch quốc, Chiến Vương, Minh Vương và Bằng Cửu lo lắng vì tổ địa mất liên lạc hơn hai tháng. Khi người ngoài vừa đề nghị trao đổi vừa uy hiếp để lấy mảnh vỡ lò luyện hư không cùng tàn khí của bảy vị Thần, các lão Vương kiên quyết cự tuyệt và yêu cầu đối phương giải thích về cuộc huyết tế năm xưa."},{"chuong":608,"tieuDe":"Tiểu Thạch Tái Hiện","tomTat":"Thạch Hạo kiểm kê hành trang trước khi rời Thạch thôn, phát hiện hai tổ khí, thần kích, pháp kiếm và chiến y Bất diệt kim thân đều bị hư hại sau trận tự bạo, trong khi kiếm gãy do Quỷ gia để lại vẫn nguyên vẹn. Nó chỉ mang theo những vật cần thiết, giữ lại phần trọng yếu của chiến y rồi cùng Thanh Phong từ biệt dân làng, chuẩn bị giải quyết công việc ở hạ giới trước khi tiến lên thượng giới. Tại hoàng cung Thạch Quốc, các lão Vương đang phẫn nộ vì các đại giáo liên tục gửi thư đòi lò luyện hư không và di vật của bảy Thần nhưng vẫn phải dè chừng lực lượng cùng pháp khí của đối phương. Thanh Phong và Thạch Hạo bất ngờ bước ra từ thông đạo trên tổ tế đàn, khiến mọi người từ kinh ngạc chuyển sang vui mừng khi xác nhận Thạch Hoàng vẫn còn sống. Sau khi kể lại quá trình cải tử hồi sinh, Thạch Hạo biết lò luyện bị nhòm ngó vì chứa hư không kim cực hiếm. Nó lập tức đảo ngược lời uy hiếp, yêu cầu các đại giáo mang pháp khí Chân Thần và bảo cụ trấn giáo tới Thạch Quốc đúng hạn, nếu không sẽ đích thân tới sơn môn lấy."},{"chuong":609,"tieuDe":"Tiểu Thạch Ra Tay","tomTat":"Thạch Hạo chỉ đạo các lão Vương dùng chính giọng điệu cứng rắn của các đại giáo để hồi đáp yêu sách giao nộp Lò Luyện Hư Không. Sau một đêm mở tiệc tại hoàng cung, Thạch Quốc nhận thư cảnh cáo về huyết kiếp, rồi huyết vân, sấm đen và phù văn nguyền rủa bất ngờ bao phủ hoàng thành. Minh Vương điều khiển đồng lô chống đỡ, trong khi Bằng Cửu và Chiến Vương nhận ra kẻ địch muốn dùng đại trận để huyết tế dân chúng. Thạch Hạo dùng Chu Tước hỏa diễm phá phù văn, gia trì đồng lô thu và luyện hóa toàn bộ huyết vân. Hắn tiếp tục vận dụng lực Côn Bằng phá hàng chục trận kỳ, bắt sống Tôn Giả đang ẩn ngoài thành rồi kéo thẳng về trung ương thiên cung. Sau khi dò xét thức hải và xác định các đại giáo tham gia âm mưu, Thạch Hạo dùng kiếm khí tiêu diệt cả thân thể lẫn nguyên thần của tù nhân. Tin một Tôn Giả bị bắt chỉ bằng một bàn tay nhanh chóng lan khắp Thạch Đô, khiến một số người nhận ra khí cơ Côn Bằng và bắt đầu nghi ngờ Tiểu Thạch đã trở về."},{"chuong":610,"tieuDe":"Quân Lâm Thiên Hạ","tomTat":"Cái chết của một Tôn Giả giữa đô thành Thạch Quốc làm thiên hạ chấn động, nhưng người đời vẫn không tin Thạch Hạo có thể là kẻ ra tay vì hắn đã bị coi là chết hơn một năm. Trong hoàng cung, Thạch Hạo mở thập đại động thiên và phóng thích nhiều linh thân mang các bảo thuật Côn Bằng, Toan Nghê, Chu Tước, Chân Hoàng cùng một linh thân hình người cầm kiếm gãy, lần lượt phái chúng tới Bắc Hải và các đại giáo để phong tỏa những Tôn Giả liên quan. Các đại giáo nhận cốt thư báo tin cùng tối hậu thư của Thạch Quốc, yêu cầu giao bảo cụ trấn giáo nếu không muốn gặp huyết kiếp. Bạch Ngọc Long Tượng của Tiểu Tây Thiên và một Tôn Giả tóc bạc của Bổ Thiên Giáo tiến tới hoàng đô, trong đó kẻ tóc bạc định dùng lực nguyền rủa sát hại các nhân vật trọng yếu của Thạch Quốc. Thạch Hạo dùng Trùng Đồng phát hiện hai kẻ địch, đích thân ra khỏi hoàng cung, vận dụng tốc độ Côn Bằng chặn đường tháo chạy và dùng lôi điện phá tan lực nguyền rủa. Hắn chém chết Bạch Ngọc Long Tượng cùng Tôn Giả tóc bạc, qua đó công khai xác nhận mình vẫn còn sống trước toàn thiên hạ. Khi các linh thân tiếp tục phong tỏa mục tiêu tại nhiều nơi, chân thân Thạch Hạo cũng lên đường tới từng đại giáo để tiến hành cuộc thanh toán."},{"chuong":611,"tieuDe":"Công Phá Thánh Địa","tomTat":"Thạch Hạo dẫn bảo thuyền trấn quốc, tam vương và mấy nghìn thị vệ vượt vực bích từ Hoang Vực sang Huyền Vực để chinh phạt Bất Lão Sơn. Trước sơn môn, tam vương yêu cầu Tần tộc giao bảo cụ trấn giáo, xử lý những kẻ thông đồng với các đại giáo và giao ra những người từng mưu hại Thạch Hạo, nhưng cao tầng Tần tộc bác bỏ và đóng cửa nghênh chiến. Đả Thần Thạch chỉ ra nhược điểm của hộ sơn thần trận không trọn vẹn, giúp ba đại Tôn Giả nhanh chóng đánh sập sơn môn. Tôn Giả Bất Lão Sơn dùng pháp khí thần linh phản công rồi tìm cách trốn, song Thạch Hạo tế dược đỉnh bạc đoạt pháp khí, đánh lão bị thương và chặn đường lui để Chiến Vương cùng Bằng Vương tiêu diệt. Đại quân Thạch Quốc tràn vào thanh trừng toàn bộ cao tầng, những kẻ từng mưu hại Thạch Hạo và lực lượng thông đồng với các đại giáo, khiến Tần tộc mất địa vị thánh địa hạ giới. Phần còn lại của đạo thống được tha vì Tần Di Ninh là mẫu thân Thạch Hạo. Do phần lớn linh dược đã bị Tiểu Tháp cùng Sinh Linh Bất Diệt ăn hết từ trước, chiến lợi phẩm chỉ còn vài pháp khí thần linh và một số thần liệu, khiến Bằng Vương đề xuất nhắm tới Tây Phương Giáo cùng Bổ Thiên Giáo."},{"chuong":612,"tieuDe":"Quét Ngang Thiên Hạ","tomTat":"Thạch Hạo phát hiện truyền tống trận siêu cấp trong Tần tộc và đưa chiến thuyền cùng quân Thạch Quốc vượt vực tới Bổ Thiên Giáo ở Trụ Vực. Sau khi từ chối hòa giải, hắn dùng đỉnh nhỏ màu bạc và năm pháp khí thần linh phá sơn môn, Tỏa Ma Trận cùng tám tòa cổ trận, còn Đả Thần Thạch tìm ra sơ hở của Bổ Thiên trận. Trải qua tám ngày, Thạch Hạo đánh vào trung tâm thánh địa, giết Tôn Giả cuối cùng, bắt sạch cao tầng và khiến đạo thống Bổ Thiên Giáo tại hạ giới gần như bị xóa tên. Trong lúc đó, linh thân Côn Bằng của hắn đánh bại hai cường tộc Bắc Hải, giết Hôi Giao Tôn Giả và Hải Ma tộc Tôn Giả rồi mang bảo tàng trở về. Thạch Hạo tiếp tục tiến đánh Tây Phương Giáo và sau mười hai ngày đã phá đại trận cuối cùng, giết hai Tôn Giả, thu toàn bộ kho tàng. Quân Thạch Quốc còn tìm thấy một thần trì chứa lượng lớn Kim Cương dịch dùng để luyện cơ thể tới cực hạn, nhưng không tìm được phương pháp phối chế. Chiến tích liên tiếp đánh hạ các đạo thống lớn khiến khắp thiên hạ chấn động."},{"chuong":613,"tieuDe":"Bình Định Hạ Giới","tomTat":"Trên đường rời Tây Phương Giáo, Thạch Hạo phân chia kho chiến lợi phẩm khổng lồ, dành dược đỉnh Chân Thần cùng nhiều pháp khí và đan dược để Thanh Phong mang về bảo vệ Thạch thôn. Hắn chọn Hàng Ma Bảo Xử làm binh khí phòng thân, trong khi Thạch Quốc thu được quyển thượng không trọn vẹn của phối phương Kim Thân dịch. Sau khi trở lại Hoang Vực, đoàn quân tiến thẳng tới Tiểu Tây Thiên; Thạch Hạo dùng bảo xử đánh xuyên cửa tiểu thế giới, tiêu diệt lực lượng chống cự và Tôn Giả còn lại của giáo này. Lý Bạch Đinh được giao tiếp quản địa bàn, biến Tiểu Tây Thiên thành thành trì thuộc Thạch Quốc và đánh dấu toàn bộ cường địch lớn tại hạ giới đã bị bình định. Thạch Hạo sau đó bế quan nửa tháng để luyện nhiều đan dược, gồm cả Tiểu Niết Bàn đan, cho Thạch Quốc và Thạch thôn. Hoàn tất việc chuẩn bị cho người ở lại, hắn quyết định tìm thiên lộ lên thượng giới, từ chối quay về Thạch thôn và rời đi giữa lời tiễn biệt nghẹn ngào của Thanh Phong cùng các vương hầu."},{"chuong":614,"tieuDe":"Thiên Lộ Bị Cắt Đứt","tomTat":"Thạch Hạo giao lại những manh mối về các tạo hóa còn ẩn tại hạ giới rồi bắt đầu hành trình tìm đường lên thượng giới. Hắn tới Thiên Thần Sơn nhưng phát hiện Thiên Nhân tộc đã rời đi và thiên lộ nơi đây không còn sử dụng được, đồng thời nhớ tới Vân Hi, Nhị Ngốc Tử, Hỏa Hoàng và Hỏa Linh Nhi. Những bí địa được ghi trong tư liệu của Tây Phương Giáo, Bất Lão Sơn và Bổ Thiên Giáo đều đã sụp đổ hoặc bị hủy, nhưng tại Trụ Vực hắn xác nhận thứ thân Nguyệt Thiền từng tự chọn bí lộ lên thượng giới. Các cổ lộ ngoài biển cũng không còn tác dụng sau khi Mạc Thương và Hàn Thiên rời đi. Thạch Hạo dùng Thất Thập Nhị Biến che giấu dung mạo, vượt qua hàng loạt thử thách của Chiến trường Bách Tộc và tìm thấy một truyền tống trận hoàn hảo tại cửa ải thứ mười. Biết đầu bên kia là lồng giam nơi sinh linh hạ giới có thể bị bắt làm tọa kỵ, hắn chủ động quay về và sau đó xác nhận hai giới đã thực sự tách rời. Khi tưởng mọi thiên lộ đều đã tuyệt đoạn, Thạch Hạo đột nhiên nhớ ra một con đường cuối cùng mà hắn tin chắc có thể thông tới thượng giới."},{"chuong":615,"tieuDe":"Con Đường Thần Ma","tomTat":"Thạch Hạo trở lại cổ địa Hỏa Quốc và đi sâu xuống Thánh Hoàng Cung Thượng cổ để truy tìm bức tường Thần Ma chân chính, với suy đoán cổ lộ phía sau có thể dẫn lên thượng giới hoặc tới Vùng cấm thần bí. Hắn liên tục vượt các Sân thi đấu, giao chiến với cự hung cùng cảnh giới và dùng trận chiến với Toan Nghê để lĩnh hội thêm bảo thuật Lôi điện. Sau hơn mười cửa, những cốt văn rời rạc giúp hắn xác định bức tường thật thường xuất hiện trong cấm địa, còn trận quyết đấu với Thao Thiết kết thúc khi hắn phá bụng thoát ra và dùng kiếm khí xuyên thủng mi tâm đối thủ. Hoàn tất các khảo nghiệm ban đầu, Thạch Hạo được một pháp trận không tên đưa tới vùng cấm rừng rậm màu đen, nơi Đả Thần Thạch giúp hắn vượt qua vô số trận pháp nguy hiểm. Hai người khảo sát các động phủ cổ và thu được một đỉnh đá cấp Thần đã gãy cả ba chân. Ở nơi sâu nhất của rừng cấm, Thạch Hạo tìm thấy bức tường Thần Ma chân chính và lập tức xông vào cửa đầu tiên. Những sinh linh tại đây mạnh hơn hẳn đối thủ trước đó, khiến hắn trải qua nhiều phen sinh tử và giết ra trong tình trạng đầy thương tích, nhưng kết quả vượt ải vẫn chưa rõ ràng."},{"chuong":616,"tieuDe":"Con Đường Bất Ngờ","tomTat":"Sau nhiều ngày quyết chiến, Thạch Hạo đi tới cuối cổ lộ nhưng phát hiện Thần Ma chi tường đã bị chặt đứt, khiến những cửa ải còn lại và con đường dự định tiến vào thượng giới không thể tiếp tục. Hắn cùng Đả Thần Thạch tìm thấy mảnh xương mang ấn ký Cung điện Chí Tôn, dấu vết của một đại trận truyền tống và dấu chân rùa khổng lồ, từ đó suy đoán một biến cố lớn từng xảy ra tại đây. Khi xác nhận bức tường đang tự chữa trị nhưng cần thời gian quá dài, Thạch Hạo từ bỏ cổ lộ và tới Hư Thần giới hỏi Điểu gia cùng Tinh Bích đại gia về con đường khác. Theo đầu mối của họ, hắn tìm kiếm quanh vùng đất cũ, gặp lại thế lực do Tử Sơn Hầu và Kim Lang dựng nên nhưng không trả thù. Thạch Hạo sau đó phát hiện di chỉ Vân tộc cùng địa cung phong ấn chứa cổ trận từng giúp cả tộc chạy khỏi cuộc tàn sát của Thôn Thiên Tước và Cùng Kỳ. Đả Thần Thạch phán đoán trận pháp có thể thông tới thượng giới, còn Thạch Hạo dù rất muốn trở về Thạch thôn lần cuối vẫn kiềm chế tình cảm. Hắn kích hoạt cổ trận, nói lời từ biệt và bước vào lối đi, chính thức biến mất khỏi hạ giới."},{"chuong":617,"tieuDe":"Thượng Giới","tomTat":"Thạch Hạo cùng Đả Thần Thạch tiến vào thiên lộ đã đoạn tuyệt, khiến giới bích rạn nứt và đường hầm hư không nhanh chóng sụp đổ. Hắn dùng Cánh Côn bằng né tránh loạn lưu, khí hỗn độn và Hư không đại liệt trảm, sau đó lần lượt dựa vào Hộp quý bằng đồng, chiếc đỉnh đá ba chân gãy và Hàng Ma xử để bảo vệ thân thể. Hộp đồng nứt thành bốn mảnh, thần đỉnh bị phá nát, còn Thạch Hạo rơi xuống mặt đất với hơn nửa xương cốt gãy nát. Sau khi tự nối xương và cầm máu, hắn xác nhận mình đã tới thượng giới nhờ linh khí nồng đậm cùng pháp tắc thiên địa hoàn chỉnh, đồng thời nhận ra sức áp chế đại đạo tại đây vô cùng mạnh. Thạch Hạo dùng Hàng Ma xử lấp hố và xóa dấu vết rồi thoát khỏi một vùng nấm khổng lồ có ánh sáng ăn mòn thần lực. Đi thêm hơn trăm dặm, hắn gặp một đội thợ săn bản địa cưỡi ốc sên khổng lồ. Một đứa bé phát hiện thương thế của hắn, và người đàn ông trung niên trong đội quyết định đưa hắn về thôn cứu chữa, mở ra cơ hội để hắn tìm hiểu thượng giới."},{"chuong":618,"tieuDe":"Trăm Sông Tụ Biển","tomTat":"Thạch Hạo được đội săn họ Chu chở về Chu thôn trong tình trạng xương cốt gần như gãy lìa và được Chu Tuấn nhận là người đầu tiên phát hiện. Sau khi Tế linh nhện trắng bạc quan sát người mới đến, Tam a công kiểm tra thương thế, cảnh báo hắn không được gây họa rồi thu xếp chỗ tạm trú để hắn tự chữa trị. Qua chuyện trò với dân làng, Thạch Hạo biết thượng giới được gọi là ba nghìn châu, nhưng con số thực tế chưa chắc đã được xác định vì mỗi châu đều vô cùng rộng lớn và bên ngoài còn có nhiều khu không người. Hắn cũng biết tiếng kèn vừa vang lên báo hiệu kỳ tuyển chọn dũng sĩ từ cấp Thôn lên Thành, Phủ, Châu và có thể dẫn tới đại chiến Ba ngàn châu, khiến hắn nghĩ tới Tần Hạo, Nguyệt Thiền, Ma nữ cùng các thiên kiêu khác. Nhận thấy pháp tắc trong cơ thể chưa hoàn thiện sau khi lên thượng giới, Thạch Hạo quyết định dùng những Niết bàn pháp đã nắm giữ để lột xác, trong khi Đả Thần Thạch phải ngủ say vì các vết nứt từ vụ nổ trên đăng thiên lộ. Hắn bố trí trận pháp phía sau Chu thôn, dựng hồ dược và dùng hơn trăm loại linh dược cùng nhiều kỳ trùng để luyện Niết bàn dịch suốt một ngày một đêm. Khi mọi thứ hoàn tất, Thạch Hạo tự đánh nát xương toàn thân, phóng thích tinh huyết rồi ngồi vào hồ Niết bàn, bắt đầu lần lột xác đầu tiên tại thượng giới."},{"chuong":619,"tieuDe":"Tái Tạo Chân Thân","tomTat":"Trong hồ Niết bàn, Thạch Hạo vận dụng pháp môn của Bất Lão Sơn, chủ động phá nát toàn bộ xương cốt, thay máu và dẫn pháp tắc hoàn chỉnh của thượng giới nhập thể. Sau một ngày một đêm, hắn hấp thu sạch tinh hoa thần tính của bảo dịch, tái tạo xương, cốt tủy và huyết dịch, khiến sức sống cùng tiềm lực tăng mạnh. Lo lần Niết bàn đầu tiên chưa đủ trọn vẹn, hắn tiếp tục dùng Chu Tước niết bàn pháp và niết bàn pháp của bộ tộc Hồng Hoàng để gột rửa, củng cố thân thể. Nhận thấy dược tính trong hồ vẫn còn, Thạch Hạo phối hợp phương thuốc cổ của Thạch thôn với linh dược để trùng tu Bàn Huyết cảnh, đạt nền tảng thân thể vượt xa cực hạn năm xưa. Pháp tắc vẫn tiếp tục dung hợp trong máu nên hắn quyết định tạm hạn chế sử dụng pháp tắc và dựa vào thân thể để tự vệ. Sau khi khôi phục dung mạo, hắn hỏi Tam a công về cuộc tuyển chọn dũng sĩ rồi cùng các thiếu niên Chu thôn chuẩn bị tới thị trấn, vừa muốn gặp người quen vừa muốn quan sát sơ đại và thiên kiêu thượng giới."},{"chuong":620,"tieuDe":"Sóng Gió Đột Nhiên Tới","tomTat":"Tam a công dẫn Thạch Hạo cùng hơn mười thiếu niên Chu thôn vượt núi rừng tới Hòe thành dự tuyển dũng sĩ. Từ lời ông về Vân tộc, Thạch Hạo nhận ra vụ nổ đường hầm hư không đã khiến mình lệch khỏi Vân châu và rơi xuống Lôi châu. Trước cửa thành, đoàn Mãng thôn dùng ngân mãng chèn ép Chu thôn, nhưng Tam a công ngăn đám trẻ phản kích và Thạch Hạo cũng nhẫn nhịn để tránh lưu lại hậu họa cho dân làng. Một đội kỵ binh Mặc Kỳ thú hộ tống nữ sứ giả ngân bào của Phủ thành tới nơi, khiến cuộc tuyển chọn chưa kịp bắt đầu đã bị gián đoạn. Tại sân diễn võ, nữ sứ giả cùng lão thành chủ công khai bức tranh cô gái tóc bạc, tiết lộ nàng đã bị đại nhân trẻ tuổi của Tiên điện đánh trọng thương sau nhiều trận giao chiến nhưng vẫn chạy thoát tới khu vực này. Thạch Hạo kinh ngạc trước thực lực của người bị truy tìm và dự cảm truyền nhân Tiên điện sẽ sớm xuất hiện. Cuối cùng, hắn thoáng thấy một tia sáng bạc gần đó, nghi cô gái tóc bạc đã bí mật tới Hòe thành."},{"chuong":621,"tieuDe":"Đại Nhân Trẻ Tuổi Của Tiên Điện","tomTat":"Vòng kim cốt châu của cô gái mặc ngân bào phát hiện dấu vết thần hi màu bạc gần Hòe thành, khiến nàng lập tức dùng đạo phù báo tin và phong tỏa hiện trường. Thạch Hạo âm thầm dùng trùng đồng quan sát, đồng thời quyết tâm tự tu thành võ đạo Thiên nhãn để không còn lệ thuộc vào ngoại lực. Đại nhân trẻ tuổi của Tiên Điện mang chiến kích hư không phá không giáng lâm, nhận định dấu vết có thể thuộc về linh thân nghi binh của cô gái tóc bạc nhưng vẫn đề phòng chân thân đang bố trí mê trận gần đó. Sau khi hắn rời thành truy đuổi, nhiều nhân vật thần bí và cường giả thuộc các thế lực lớn tiếp tục xuất hiện tại Hòe thành. Cuộc tuyển chọn của thịnh hội Trăm sông đổ về biển được nối lại, còn Thạch Hạo che giấu thực lực vì cơ thể vẫn đang trong thời kỳ lột xác. Chân Cổ cùng nhiều sơ đại lần lượt hiện thân, cho thấy một biến cố lớn đang thu hút thiên kiêu khắp nơi. Cuối chương, Thạch Hạo phát hiện Ma nữ rồi nhìn thấy Nguyệt Thiền nắm tay đại nhân trẻ tuổi của Tiên Điện, cả hai cùng phát sáng và tìm kiếm một mục tiêu chưa rõ."},{"chuong":622,"tieuDe":"Thiên Kiêu Cùng Nổi Lên","tomTat":"Thạch Hạo chứng kiến chủ thân Nguyệt Thiền và Đại nhân trẻ tuổi của Tiên Điện bay qua Hòe thành, đồng thời nhận ra thần hồn nàng đã giải phóng thêm sức mạnh bất hủ. Tại cuộc tuyển chọn địa phương, các thiếu niên Chu thôn dù có thể nâng đại đỉnh vạn cân vẫn không lọt vào mười vị trí đầu, trong khi Mãng thôn có người vượt qua. Thiểm Điện Tử dùng lôi điện giết nhóm Tôn Giả từng gài bẫy mình rồi ép những người còn lại tiết lộ lời đồn rằng cô gái tóc bạc đã lấy Tam thế đồng quan hoặc tìm thấy Cung điện Chí tôn. Trên đường trở về, Thạch Hạo nhìn thấy Đằng Nhất một mình giao chiến với đàn Hoàng Kim Nghĩ nhưng vẫn nhẫn nại không tham chiến để tiếp tục che giấu thân phận. Sau năm ngày, phù văn trong cơ thể hắn được bù đắp hoàn toàn, giúp hắn khôi phục khả năng vận dụng bảo thuật và không còn phải tự phong ấn. Hắn săn Long giác tượng cùng Song đầu hỏa tê cứu trợ Chu thôn rồi tiến sâu vào núi tìm tạo hóa. Tại đó, Thạch Hạo phát hiện chân thân Ma nữ cùng một thanh niên mang đèn thần đang đối đầu chủ thân Nguyệt Thiền và Đại nhân trẻ tuổi của Tiên Điện, nhưng cuộc giao chiến chưa bùng nổ."},{"chuong":623,"tieuDe":"Ngân Hoàng","tomTat":"Đại nhân trẻ tuổi của Tiên Điện dùng chiến kích hư không khiêu chiến chàng trai thần bí dưới kim đăng, còn đối phương lấy kim đăng và bảo thuật Chân Long chống đỡ. Hai người đều đã đạt Tôn Giả đại viên mãn nhưng cố ý chưa nhen nhóm Thần hỏa, sau cuộc giao phong bất phân thắng bại liền chủ động dừng tay. Ma nữ cũng khiêu chiến chủ thân của Nguyệt Thiền, song hai túc địch chỉ giao đấu ngắn rồi tách ra trước sự quan sát của nhiều sơ đại. Thạch Hạo đánh giá hai nam thiên kiêu là cao thủ cái thế cùng cảnh giới và kiềm chế ý định đoạt chiến kích vì sợ để lộ tung tích tại thượng giới. Trong khi đám đông tiếp tục tìm cô gái tóc bạc bị thương, hắn trở lại khu vực gần Chu thôn và phát hiện một chim non toàn thân trắng bạc trong tổ chim cánh bạc. Chim non mang mùi bảo dược, hiểu lời nói và biểu lộ tức giận, khinh thường lẫn xấu hổ giống con người, khiến Thạch Hạo nghi ngờ nó không phải hung cầm phản tổ bình thường. Hắn giấu chim non vào tay áo mang đi, còn chim trưởng thành không truy cản mà tỏ ra nhẹ nhõm, để lại bí ẩn về thân phận thật của sinh linh màu bạc."},{"chuong":624,"tieuDe":"Diệu Thủ Ngẫu Nhiên Mà Có","tomTat":"Thạch Hạo bắt được một con chim non toàn thân ánh bạc và nghi ngờ nó là Ngân Hoàng có liên quan đến bảo thuật Chân Hoàng. Hắn dùng Trùng đồng cùng thần thức thăm dò nhưng đều bị hào quang bạc và ngân diễm phù văn trong cơ thể nó ngăn cản, còn việc cưỡng ép kiểm tra có thể khiến chim non giải thể. Thạch Hạo quyết định giữ nó bên mình, lần lượt đề xuất tên Tứ Bạch rồi đặt tên là Bạc bất chấp thái độ phản đối của nó. Trong lúc nhiều tu sĩ tiếp tục tìm kiếm cô gái tóc bạc, một quái sư bói rằng mục tiêu vẫn chưa rời khỏi khu vực. Bạc nhiều lần bỏ trốn nhưng đều thất bại, thậm chí phải tự quay về khi bắt gặp Thiểm Điện Tử giao chiến dữ dội ngoài thôn. Để tránh nó bị nhận ra, Thạch Hạo dùng cốt tiễn cắt sạch bộ lông trắng bạc, lông đuôi và linh vũ trên đầu, biến nó thành hình dạng giống chim bồ câu. Bạc tức giận phát ra giọng thiếu nữ và âm thầm thề rằng sau khi khôi phục chân thân sẽ ném Thạch Hạo vào miệng núi lửa, trấn áp hắn một trăm năm."},{"chuong":625,"tieuDe":"Tìm Tổ Phụ Đại Thần Ma","tomTat":"Tin tức về Tam Thế Đồng Quan và Cung Điện Chí Tôn khiến nhiều cường giả hội tụ quanh Hòe thành, nơi truyền nhân Tiên Điện phối hợp với một trưởng lão Bổ Thiên Giáo giết con giun đã nhen nhóm Thần Hỏa. Thạch Hạo đưa Bạc rời khỏi vòng xoáy, bí mật diệt những hung nhân có thể gây họa cho Chu thôn rồi cùng Đả Thần Thạch nghiên cứu đại trận phong tỏa suốt hai ngày để tìm đường thoát. Biết mình đang ở Lôi châu, hắn dùng truyền tống trận liên châu tới Ngũ Hành Châu nhằm vừa tu hành vừa tìm kiếm Thập Ngũ Gia. Tại địa bàn Bất Lão Sơn, hắn nghe tin Tần Hạo sở hữu hai khối Tiên cốt, uy chấn cùng thế hệ, trong khi nguồn gốc khối xương từng thuộc về ca ca bị thế lực này nghiêm cấm bàn luận. Sau nửa tháng thăm dò, Thạch Hạo biết Thạch Tử Lăng từng đại náo Bất Lão Sơn rồi tới đảo Ác Ma tìm người, từ đó nghi Thập Ngũ Gia và A Man có thể đang mất tích hoặc bị giam giữ. Tin rằng họ vẫn còn sống, hắn quyết tâm tiếp tục điều tra và đối đầu Bất Lão Sơn cùng Tần tộc. Để tránh bại lộ thân phận khi chưa đủ mạnh, Thạch Hạo bỏ tên thật trong lúc hành tẩu tại thượng giới và tự xưng Hoang Thiên."},{"chuong":626,"tieuDe":"Đảo Thần Ma","tomTat":"Thạch Hạo khảo cứu kỹ những lời đồn về đảo Ác Ma rồi theo đoàn người sử dụng truyền tống trận siêu cấp vượt hơn ngàn vạn dặm. Từ điểm truyền tống, họ thuê thuyền bay bằng gỗ lôi quang để đi qua vùng sương mù tám trăm dặm, nơi cốt đăng của người lái thuyền đã đẩy lui một cự thú mắt đỏ. Trên đường, Thạch Hạo tiếp tục lĩnh hội Vạn Linh đồ và tự nhắc mình không được tùy tiện dùng bảo thuật Côn Bằng ở thượng giới để tránh lộ thân phận. Đoàn khách lên đảo quy tụ nhiều cường giả cùng thiên tài, nổi bật là thanh niên tộc Thao Thiết muốn tìm tiên huyết, người trẻ tuổi thuộc bộ tộc Cổ Kim Loan và một thanh niên tái nhợt khiến Thạch Hạo đặc biệt cảnh giác. Thạch Hạo biết đảo được chia thành khu nhà tù và tuyệt địa, đồng thời nghe truyền thuyết về Ma tôn, sinh linh cấm kỵ cùng Mộ tiên nằm sâu trong vùng nguy hiểm. Khu nhà tù giam giữ cả sinh linh Thần Hỏa lẫn Thiên Thần, phong bế tu vi rồi ép họ xuống các hầm mỏ nguyền rủa khai thác thần liệu lôi đạo. Thay vì theo số đông tìm tạo hóa trong tuyệt địa, Thạch Hạo chọn khu nhà tù để dò tìm tổ phụ. Trước khi bắt đầu điều tra, hắn đã nghe được rằng Đại Ma Thần Thập Ngũ Gia là một nhân vật rất nổi tiếng tại đảo Ác Ma."},{"chuong":627,"tieuDe":"Tin Tức Của Tổ Phụ","tomTat":"Thạch Hạo theo đoàn người mới tới khu khai thác trên đảo Ác Ma, chứng kiến cai ngục dùng roi sét hành hạ phạm nhân và lấy thi thể sinh linh đã đốt Thần Hỏa để răn đe. Sau hơn nửa tháng giả làm người đào mỏ, hắn biết Thập Ngũ Gia bị Tần tộc đày tới đây vì đã cho A Man dùng viên thần đan mà chúng muốn chiếm đoạt. Tổ phụ hắn từng nuốt một vật thần bí đào được trong mỏ, chặt đứt xiềng xích, đánh Tần Trình Thượng gần tan nát, giết hơn mười cường giả Tần tộc rồi chạy sâu vào tuyệt địa và mất tung tích. Thạch Hạo cũng xác nhận A Man không bị đưa tới đảo mà đang bị giữ tại Bất Lão Sơn. Khi khảo sát một phế mỏ bằng Trùng Đồng, hắn phát hiện kỳ trân tỏa hào quang cực thịnh nằm sâu trong tầng đá. Hắn đánh thức Đả Thần Thạch để bàn cách đoạt bảo, đồng thời dự tính phá Hắc Ngục và thả những tù nhân từng đối địch với Bất Lão Sơn nhằm tạo đại loạn. Kế hoạch càng nguy hiểm khi có tin Hắc Ngục đang trấn áp một số Chân Thần Thượng Cổ."},{"chuong":628,"tieuDe":"Bạo Động","tomTat":"Thạch Hạo và Đả Thần Thạch khảo sát Hắc ngục trên đảo Ác Ma nhưng từ bỏ ý định phá sâu vì trận pháp cấp Giáo chủ và lời đồn về một Thiên Thần cổ xưa bị phong ấn. Trong khi người Tần tộc tiếp tục đánh đập và ép các phạm nhân mang nguyền rủa đào mỏ, Đả Thần Thạch dùng Trùng đồng tìm lôi điện trong địa mạch rồi bố trí thế dẫn lôi tới tầng phong ấn ngoài cùng. Lôi điện phá hỏng phù văn và khiến lực lượng cai ngục phải tập trung trấn áp, tạo cơ hội để hai người đào được cây cỏ năm lá cùng hòn đá chứa lôi điện và phù văn thần bí. Họ phong ấn hai địa bảo vào Hàng Ma xử, sau đó để Đả Thần Thạch nuốt pháp khí nhằm che giấu khí tức. Nhiều phạm nhân nhân cơ hội phá gông xiềng, giải cứu đồng bạn và giao chiến với cai ngục, còn Thạch Hạo âm thầm giúp cuộc nổi dậy lan rộng. Trong hỗn loạn, Thạch Hạo dùng hai quyền mang lôi đình giết Tần Trình Thượng rồi diệt những người Tần tộc chứng kiến. Rời khỏi khu bạo động, hắn tiến vào khu tuyệt địa đầy sương mù và lôi điện để nghiên cứu thu hoạch mới, đồng thời hy vọng tìm thấy tổ phụ."},{"chuong":629,"tieuDe":"Tuyệt Địa Của Ma Tôn","tomTat":"Thạch Hạo tiến sâu vào đảo Ác Ma, dùng Bảo Thuật Toan Nghê giết ác ngư Lôi thuộc tính nhưng phải rút lui khi bị cả đàn cá có sinh linh nhen nhóm Thần hỏa truy đuổi. Sau nhiều ngày vượt sương mù điện từ, hắn tới các cốt tháp trú ẩn do tiền nhân để lại và biết Bất Lão sơn đã chuyển từ lùng bắt sang tìm cứu Lão Thập Ngũ, song vẫn chưa có tin tức về ông. Thạch Hạo tiếp tục săn sinh linh Lôi thuộc tính, giết hơn trăm cổ ngạc để thu lôi thạch và kịp tránh một đại mãng Thần cấp từng thiêu nhiều Tôn giả thành tro. Vượt qua tòa tháp hải đăng cuối cùng, hắn tiến vào khu vực nguy hiểm nhất và phát hiện dòng sông trắng bạc pha ánh vàng chảy trên vòm trời, bên trong có nhiều Thần thi và Thiên Thần thi bất hủ. Các tu sĩ kể nhiều giả thuyết về dòng sông, sức mạnh nguyền rủa và ngôi mộ Tiên ở điểm cuối, rồi dẫn hắn tới phế tích cổ thành của Ma tôn. Tại đây, Thạch Hạo biết tấm bia khổng lồ có thể kiểm nghiệm sức chiến đấu, thiên phú và tiềm năng, đồng thời thấy dấu ấn Tần Hạo sáng hơn cả Tần Trường Sinh. Sau khi xác nhận khảo nghiệm không gây nguy hiểm, hắn nảy ý định tự mình thử sức."},{"chuong":630,"tieuDe":"Lưu Danh Thần Bia","tomTat":"Bên bờ thiên hà trên đảo Ác Ma, hàng trăm sinh linh tụ tập trước một cổ bia cao ba ngàn trượng để kiểm tra sức chiến đấu, thiên phú và tiềm năng, nhưng phần lớn đều không đủ tư cách chen vào ba triệu thứ hạng. Thanh Ngọc của Giao tộc khiến bảo huyết phát sáng, giao cảm thành công với thần bia và trở thành người duy nhất trong đoàn hiện tại được lưu danh, dù chỉ đứng ở cuối bảng. Mọi người sau đó phát hiện Tần Hạo đồng hạng nhất về thiên phú với hai nhân vật cổ đại, vượt trên Tần Trường Sinh, còn hai Tiên cốt của hắn vẫn đang cộng hưởng nên chưa thể kiểm tra sức chiến đấu. Thạch Hạo từ chối thử sức trước đám đông và chấp nhận bị chế giễu nhằm tránh thu hút sự chú ý. Khi mọi người đã rời đi, hắn quyết định không kiểm tra thiên phú vì từng hai lần mất Chí Tôn cốt mà chỉ đánh giá sức chiến đấu. Đòn đánh của hắn khiến Lưu Danh Thần Bia lay động, hoa đại đạo cùng tiên quang tràn ngập trời cao. Dị tượng truyền xa khiến đoàn người quay lại kinh hãi, còn Thạch Hạo bay lên khắc chữ nhưng thứ hạng cuối cùng chưa được công bố."},{"chuong":631,"tieuDe":"Chấn Kinh Mười Châu","tomTat":"Dấu vết do Thạch Hạo lưu lại dưới danh Hoang được thần bia gia trì, hóa thành hình người ngồi xếp bằng cầm bút và vượt lên trên toàn bộ bảng sức chiến đấu. Tin Hoang đứng đầu nhanh chóng truyền khỏi Ngũ Hành châu, khiến các đại giáo, thiên kiêu, sơ đại và nhiều nhân vật cấp Bá chủ đổ tới Đảo Ác Ma. Thạch Hạo nhân lúc mọi người bàn luận đã độn xuống lòng đất, định nhổ thần bia để luyện thành pháp bảo nhưng kiệt sức vẫn không thể lay chuyển nó. Bất Lão Thiên Tôn đưa Tần Hạo tới xem dấu vết, còn Tần Hạo tuyên bố sẽ hợp nhất hoàn toàn hai khối Chí Tôn cốt rồi trở lại đánh văng hình khắc của Hoang. Sau khi rời phế thành, Thạch Hạo tiếp tục men theo thiên hà về phía mộ Tiên để tìm tạo hóa. Trải qua nửa tháng quan sát phù văn trên dị thảo màu vàng và nghiên cứu lôi đình, hắn phá vỡ ràng buộc của Bảo Thuật Toan Nghê, khiến hình thể Toan Nghê phân giải thành vô số phù văn thiểm điện và mở ra bước tiến mới trên con đường lôi đình."},{"chuong":632,"tieuDe":"Được Pháp Môn","tomTat":"Thạch Hạo cảm ngộ bên thiên hà trên đảo Ác Ma, khiến lôi pháp vượt khỏi ràng buộc của bảo thuật Toan Nghê và mở ra ý tưởng tự khai sáng một thần thông cấm kỵ. Hắn thử thành quả bằng cách tiêu diệt một con thằn lằn bạc cảnh giới Tôn Giả, sau đó tiếp tục nghiên cứu cây cỏ năm lá màu vàng cùng hòn đá lôi điện nơi nó cắm rễ. Khi tiến sâu tám ngàn dặm giữa sức nguyền rủa ngày càng mạnh, hắn tìm thấy lời nhắn của tổ phụ trên một ngọn núi đá và xúc động đáp lại rằng mình vẫn còn sống. Gần một tháng sau, Thạch Hạo gặp sơ đại Lý Vân Thông của Thiên Vẫn châu, người từng bị một Trùng đồng giả áp chế và đánh bại. Mô tả về đối thủ khiến Thạch Hạo nghi người đó có liên hệ với Thạch Nghị, nhưng chưa có bằng chứng xác nhận. Hai người trao đổi bản hoàn chỉnh của bảo thuật Toan Nghê và pháp môn Lôi Thiên tước, đồng thời Lý Vân Thông chỉ cho Thạch Hạo cách luyện dị thảo thành dịch để hỗ trợ Lôi đạo. Sau khi nghe kể về Lôi Thần mộc lấy từ thiên hà, cả hai tách ra bế quan và Thạch Hạo bắt đầu luyện hóa cây dị thảo thành chất lỏng màu vàng chứa đầy phù văn."},{"chuong":633,"tieuDe":"Thu Hoạch Dồi Dào","tomTat":"Thạch Hạo luyện hóa cây dị thảo năm lá thành kim dịch chứa tàn văn và khí tức lôi đình Tiên đạo, sau đó điều chỉnh lượng hấp thu để tránh bị dược lực bá đạo làm trọng thương. Nhờ vận chuyển pháp Lôi Thiên tước trên nền tảng bảo thuật Toan Nghê, hắn tu pháp môn này tới cảnh viên mãn rồi dung hợp các hệ phù văn thành một bảo thuật Lôi đình mạnh hơn trước. Hắn tiếp tục trợ giúp Đả Thần Thạch phân giải kỳ thạch lôi điện, thu lấy phù văn và khí tức lôi đình, còn Đả Thần Thạch ăn sạch phần đá để chữa lành thân thể rạn nứt. Cả nhóm men theo thiên hà về phía Mộ tiên, nhìn thấy nhiều thi thể cùng pháp khí quý giá nhưng không thể tiếp cận vì lôi điện và nguyền rủa quá nguy hiểm. Khi phát hiện một cổ thi gần bờ cầm lò luyện đan bằng bảo cốt, Thạch Hạo liều mình ra tay và chịu trọng thương nhưng vẫn đoạt được pháp khí. Bên trong lò có mấy chục cây bảo dược còn nguyên sinh cơ từ thời thượng cổ, và cây đầu tiên hắn lấy ra được xác định là một thánh dược có cánh hoa tím."},{"chuong":634,"tieuDe":"Thao Thiết","tomTat":"Thạch Hạo kiểm kê lò luyện đan lấy từ thiên hà và phát hiện năm mươi bốn cây dược, gồm hai thánh dược, một chuẩn thánh dược cùng nhiều linh dược quý hiếm cần cho đan phương Thạch Tộc. Kho dược liệu giúp hắn tiến gần hơn tới kế hoạch dùng pháp tắc hoàn chỉnh của thượng giới để trùng tu các đại cảnh giới và gột rửa thân thể. Trong lúc hắn chữa thương và luyện hóa nguyền rủa, một lão già áo xám đã nhen nhóm Thần hỏa bất ngờ đánh lén nhằm cướp bảo lô, nhưng bị Đả Thần Thạch dùng Thiểm điện quyền đánh trọng thương. Thanh niên áo tím tộc Thao Thiết cùng đoàn tùy tùng xuất hiện và ra lệnh giết Thạch Hạo để chiếm cả bảo lô lẫn Đả Thần Thạch. Thạch Hạo đánh vào thiên hà, dẫn động thiên lôi cùng nguyền rủa rồi ẩn trong bảo lô, khiến phần lớn đoàn đối phương bị tiêu diệt và nhiều pháp khí Thượng cổ vỡ nát. Khi rời bảo lô, hắn phải một mình chịu sức nguyền rủa, suýt thân tử đạo tiêu và mất thêm hai ngày mới hồi phục. Sau đó hắn giết lão già áo xám, bắt sống thanh niên áo tím rồi tiếp tục bôn ba tới nơi sâu nhất của thiên hà, nơi một ngôi mộ cổ khổng lồ đón nhận toàn bộ dòng nước."},{"chuong":635,"tieuDe":"Mộ Tiên","tomTat":"Thạch Hạo và Thao Thiết đến gần Mộ tiên, nơi thiên hà chảy vào ngôi mộ khổng lồ giữa lôi đình, sương mù và nguyền rủa. Biết Thạch Hạo định giết mình làm thức ăn, Thao Thiết ra tay trước rồi phá phong ấn tích trữ thần lực, chấp nhận hủy đạo cơ để liều mạng, nhưng cuối cùng vẫn bị một tia sét giết chết sau khoảng một trăm năm mươi hiệp. Thạch Hạo không lấy được thần thông Thôn phệ vì cấm chế và nguyên thủy chân cốt tự hủy, nên dùng lò luyện đan hầm thi thể rồi ăn nửa con để tích trữ thần lực. Hắn mất sáu ngày vượt chặng nguyền rủa cuối cùng, đến chân mộ và dùng Trùng đồng phát hiện máu đỏ mang khí tức bất hủ trên đỉnh nhưng chưa đủ sức tiếp cận. Không thể vào trong, hắn ngồi trước mộ cảm ngộ suốt một tháng, nhận ra nhiều dạng biến hóa của lôi đình và nắm được cách khiến lôi đình hóa thành hỏa diễm mang sức hủy diệt. Khi đi vòng quanh Mộ tiên, Thạch Hạo phát hiện kỳ thảo, cây thấp và búp hoa đều quấn ánh chớp, ẩn chứa phù văn lôi đình thần bí."},{"chuong":636,"tieuDe":"Gặp Tổ Phụ","tomTat":"Sau khi luyện hóa Lôi Thần mộc và tiếp tục tu luyện bảo thuật Toan Nghê, Lý Vân Thông trở lại thần bia rồi kinh ngạc phát hiện Hoang đã đứng trên Tần Trường Sinh trong bảng xếp hạng sức chiến đấu cùng cấp. Tin tức khiến cao thủ Bất Lão sơn và người của nhiều đạo thống kéo tới đảo Ác Ma, trong đó có phe muốn lôi kéo Hoang. Thạch Hạo đọc được lời nhắn cho thấy tổ phụ vẫn tưởng mình đã chết nên quyết mở rộng phạm vi tìm kiếm, đồng thời kiểm nghiệm khả năng biến lôi điện thành hỏa diễm và tránh các sinh linh cấp Thần. Hoàng điệp bộc lộ uy thế huyết mạch, khiến các đàn ngân điệp, bọ cánh vàng và nhiều chủng tộc quần cư thần phục rồi tham gia tìm kiếm người cụt tay. Từ những manh mối liên tiếp, Thạch Hạo phát hiện có người đang truy sát tổ phụ và bí mật bám theo một đôi nam nữ trung niên tới đại trận niêm phong. Tại đó, Thạch Trung Thiên bị tám cường giả vây giết vì có thế lực không muốn ông gặp gỡ hoặc dạy bảo Tần Hạo. Khi đối phương dùng tin Thạch Hạo đã chết để đả kích ông, Thạch Hạo xuất hiện trong nước mắt và lên tiếng báo rằng mình vẫn còn sống."},{"chuong":637,"tieuDe":"Gặp Lại","tomTat":"Thạch Hạo bí mật quan sát khi Thạch Trung Thiên bị hai cường giả đã nhen nhóm Thần hỏa cùng sáu Tôn giả vây khốn, đồng thời đau lòng nhận ra tổ phụ đã già nua vì tin hắn tử trận. Phe truy sát muốn giết Thạch Trung Thiên để tránh lão ảnh hưởng đến quá trình trưởng thành của Tần Hạo, còn lão tuyên bố mình không muốn quay lại Bất Lão Sơn và chỉ tiếc chưa thể gặp trưởng tôn. Chờ lão già áo tím dồn sự chú ý vào mục tiêu, Thạch Hạo bất ngờ lao ra, dùng Hàng Ma Xử gia trì lôi điện đánh nát nửa thân lão. Hắn đồng thời tế lò luyện đan xuyên thủng ngực phải và phá hủy cánh tay phải của bà lão, khiến cả hai cường giả Thần cấp trọng thương nhưng chưa chết. Sau đó Thạch Hạo dựng phù văn bảo vệ tổ phụ, khôi phục dung mạo thật và xác nhận mình vẫn còn sống. Thạch Trung Thiên nhận ra trưởng tôn qua huyết mạch và tình cảm chân thành, từ bi thương chuyển sang vui mừng, trong khi những người xung quanh kinh hãi khi biết thiếu niên chí tôn hạ giới đã lên Thượng giới."},{"chuong":638,"tieuDe":"Trùng Quân","tomTat":"Thạch Hạo và Thạch Trung Thiên chính thức đoàn tụ sau hơn mười năm chia lìa, khiến vị tổ phụ xúc động rơi lệ khi biết cháu mình vẫn còn sống. Thạch Hạo phát hiện ông đã cụt tay và mang vết chém gần bổ đôi thân thể nên lập tức lấy thánh dược chữa trị, đồng thời hứa sẽ luyện bảo đan giúp ông hoàn toàn hồi phục. Phe truy sát vẫn quyết định giết hai ông cháu, còn bà lão nhen nhóm Thần hỏa kích hoạt Phục ma trận nhưng trận pháp nhanh chóng bị Đả Thần Thạch gặm sạch bảo liệu. Cuộc đối thoại kéo dài vốn là kế hoãn binh của Thạch Hạo để Hoàng điệp triệu tập đại quân trùng tộc trên đảo Ác Ma. Bọ cánh vàng, Hành thổ tằm và Ngân điệp đồng loạt bao vây chiến trường, dùng tơ, lôi điện cùng phù văn hợp lực áp đảo đối phương. Ông lão áo tím bị phá nát thân thể chỉ còn đầu lâu, bà lão bị chấn thành nhiều khúc, còn sáu Tôn Giả rơi vào tuyệt cảnh. Khi đại cục đã định, Thạch Hạo tuyên bố những kẻ này không xứng trở thành điểm khởi đầu cho cuộc chiến thật sự của hắn tại thượng giới."},{"chuong":639,"tieuDe":"Sợ Chuyện Không Đâu","tomTat":"Thạch Hạo dùng Hàng ma xử giết mụ già đã nhen nhóm Thần hỏa rồi thẩm vấn sáu Tôn giả thuộc lực lượng bí mật của Tần tộc. Hắn biết hộ pháp Tần Côn Luân đã ra lệnh giết Thạch Trung Thiên để ngăn ông gặp Tần Hạo, đồng thời phát hiện Thiên quốc cũng phái Quang thiên sứ tham gia truy sát. Sau khi hai kẻ chống đối bị chém đầu, ông lão áo tím tự bạo và cuốn những tù binh còn lại vào vụ nổ. Thạch Hạo định dùng Tử Kinh Nguyệt cứu tổ phụ nhưng được biết người trước mặt chỉ là linh thân đã bị huyết kiếm chém trọng thương, còn chân thân Thạch Trung Thiên đã rời đảo Ác Ma sau khi nhờ chân huyết cấm kỵ trốn khỏi cổ quáng. Linh thân tiêu tán thành mưa sáng, khiến Thạch Hạo phải nhờ Hoàng điệp và Hắc tinh trùng tiếp tục tìm kiếm chân thân. Qua hình ảnh do đầu lĩnh Hắc tinh trùng truyền lại, hắn biết Quang thiên sứ đang huấn luyện hai thiên tài trẻ khai thác nỗi đau mất tôn nhi của Thạch Trung Thiên để dựng sát cục. Thiên quốc dự định khuếch trương cuộc chiến thành danh của Tần Hạo tại bí cảnh Ngũ hành châu, lợi dụng quan hệ ông cháu để dụ Thạch Trung Thiên xuất hiện."},{"chuong":640,"tieuDe":"Thịnh Hội Cỡ Nhỏ","tomTat":"Thạch Hạo thoát khỏi đảo Ác Ma sau nhiều tháng sống giữa sương mù điện từ rồi tiếp tục hành trình tìm kiếm tổ phụ. Tại một tửu lâu, hắn biết Bất Lão sơn đang triệu tập các sơ đại và truyền nhân tới bí cảnh Nguyên Thiên để luận bàn, trong khi Tần Hạo cùng hai khối Chí Tôn cốt trở thành tâm điểm dư luận. Từ việc cha mẹ mình sắp xuất hiện cùng Tần Hạo và những tin tức do Quang thiên sứ khuếch đại, Thạch Hạo nhận ra Thiên quốc đang dựng sát cục nhằm dụ Thạch Trung Thiên tới bí cảnh. Hắn dùng Thất Thập Nhị Biến hóa thành nhiều tu sĩ, đi qua các cự thành công khai chuyện Tần tộc từng giam tổ phụ trên đảo Ác Ma và việc Thiên quốc đang truy sát ông. Tin tức được những người vượt ngục xác nhận một phần, khiến Bất Lão sơn và Tần tộc vướng vào bê bối. Tại cổ thành Nguyên Thiên, Nguyệt Thiền, truyền nhân Tiên điện, Thiểm Điện Tử, Thanh Tiên, Đằng Nhất, Chân Cổ, Ma nữ và Hoàng Vũ lần lượt hiện thân trước ngày bí cảnh mở cửa. Cuối cùng, đoàn Bất Lão sơn tiến vào thành; Thạch Hạo nhìn thấy cha mẹ cùng Tần Hạo nhưng vẫn chưa tìm được Thạch Trung Thiên."},{"chuong":641,"tieuDe":"Nơi Phong Ấn","tomTat":"Thạch Hạo cùng đám tu sĩ tiến vào một vùng linh khí nồng đậm trong bí cảnh Nguyên Thiên, nơi cung Hỏa Ma đang chiếm giữ sơn cốc trung tâm. Một tu sĩ vừa đào được Khuyển diệp đằng đã bị người canh giữ tóc tím dùng xích tiễn giết chết và đoạt dược, khiến Thạch Hạo quyết định không mạo hiểm đối đầu trực diện với các cường giả Thần cấp. Khi dò xét xung quanh, mọi người phát hiện phạm vi trăm dặm đã bị đại trận Thần cấp cổ đại phong kín, còn những người cưỡng ép vượt trận đều bị phù văn giết chết. Một cường giả Xích vũ hạc đã nhen nhóm Thần hỏa sau đó lao ra khỏi sơn cốc trong tình trạng trọng thương, chứng minh mật địa bên trong ẩn chứa hiểm họa đáng sợ. Nhân mã cung Hỏa Ma dựa vào bốn cường giả Thần cấp để gom và áp giải các tu sĩ vào sơn cốc, tuyên bố đây là lối thoát duy nhất. Bên trong, họ nhìn thấy phế tích thánh thổ, Hoàng kim sơn, Lôi kích mộc còn sinh cơ và một vườn dược hoang phế giữa vô số phù văn nguy hiểm. Cung Hỏa Ma lấy danh nghĩa cùng thăm dò và cứu viện để buộc những người ngoài phe đi trước dò cấm chế, thực chất đẩy họ vào chỗ chết."},{"chuong":642,"tieuDe":"Ma Quỷ Huyết Thần Thụ","tomTat":"Hoàng kim sơn sụp đổ, khiến cung điện hoàng kim bị rễ Lôi kích mộc kéo lên và hiện nguyên hình là bộ xương vàng của Long ngao. Hơn hai mươi tu sĩ thoát khỏi xương sọ, tiết lộ bên trong có bồ đoàn và tượng thần từng khiến bốn cường giả cung Hỏa Ma kích phát sát cơ. Khi ý chí cổ thụ dần tỉnh lại, nó dùng cành cây và sấm chớp truy sát Thạch Hạo, đồng thời giết nhiều tu sĩ chạy cùng hướng. Thạch Hạo bị đánh thổ huyết nhưng nhận ra mục tiêu thực sự của cổ thụ là lò luyện đan chứa khí tức lôi đình Tiên đạo. Sau khi hút sức mạnh trong lò, Lôi kích mộc bị nguyền rủa Mộ tiên phản phệ, khô héo, rụng lá rồi buông di cốt Long ngao để tháo chạy. Thạch Hạo lập tức thu hồi lò, tiến vào xương sọ và dùng Trùng đồng phát hiện tờ giấy vàng giấu trong bồ đoàn. Hắn lấy tờ giấy nghi là truyền thừa Long ngao rồi rời khỏi hiện trường trước khi cổ thụ hoặc bốn cường giả cung Hỏa Ma quay lại."},{"chuong":643,"tieuDe":"Bí Cảnh Đầy Nguy Hiểm","tomTat":"Thạch Hạo cùng mười mấy tu sĩ sống sót thoát khỏi khu vực phong ấn sau khi hoàng kim sơn sụp đổ và trận pháp tan rã, nhưng hắn giữ kín tờ giấy vàng vừa thu được. Sau khi chứng kiến hai thần linh giao chiến, phần lớn những người sống sót quyết định ẩn náu, còn Thạch Hạo tiếp tục đi sâu vào bí cảnh; phía sau, họ bắt đầu nghi hắn chính là Hoang. Xích Lăng Không dẫn ba cường giả Cung Hỏa Ma quay lại tìm tạo hóa, nhưng một người bị Ma huyết quỷ thần thụ giết và những người còn lại phải tháo chạy. Sự xuất hiện của cổ thụ khiến Xích Lăng Không nghi Bí cảnh Nguyên Thiên nối với khu vực không người của thượng giới. Đi thêm chín ngàn dặm, Thạch Hạo phát hiện đàn Hắc lân trùng cùng Ngân trùng vương, dược liệu quý có thể giúp hắn chuẩn bị trùng tu cảnh giới. Khi hắn dùng bàn tay sấm sét bắt thần trùng, người hầu Tiên điện bắn tên phù văn ngăn cản và tuyên bố đã chờ con trùng này từ lâu. Chủ thân Nguyệt Thiền và Tần Hạo sau đó lần lượt xuất hiện, khiến cuộc tranh đoạt Ngân trùng vương trở thành nơi nhiều cường giả cùng hội tụ."},{"chuong":644,"tieuDe":"Ma Vương Giết Thiên Kiêu","tomTat":"Thạch Hạo lấy danh xưng Ma vương, dùng nhịp bước tạo đại thế rồi một mình đối đầu Trần Thanh, Chân hống tử kim và cô gái Long tước bên hồ Ngân long liên. Hắn dùng bảo xử xương trắng chặn Khốn thần tác, phá trận văn và mở động thiên duy nhất hóa giải bảy tên Tru thần của Trần Thanh. Khi Trần Thanh tung rỉ đồng nguyền rủa, Thạch Hạo nhận ra vật từng khiến mình tịch diệt ở hạ giới, giam phù văn rồi trả ngược vào đối thủ trước khi chém hắn; mệnh phù răng thú lập tức tái tạo thân thể và đưa Trần Thanh về tế đàn. Thạch Hạo tiếp tục đánh gãy xương Chân hống tử kim, vượt qua tiếng gào đại thần thông và đề nghị thu nó làm tọa kỵ, nhưng cuối cùng chém đầu khi nó không chịu khuất phục. Cô gái Long tước hoảng sợ bỏ chạy, hiện bản thể giao chiến và cũng bị hắn đánh bại rồi truyền khỏi bí cảnh. Tại tế đàn, lời kể của ba thiên kiêu xác nhận họ đều thua cùng một thiếu niên, khiến ngoại giới nhận ra Ma vương đã liên tiếp loại những người mạnh hàng đầu. Trần Thanh không dám quay lại tìm Thạch Hạo mà yêu cầu được truyền tống tới chỗ đại nhân trẻ tuổi của Tiên điện, trong khi các Giáo chủ và đại giáo bắt đầu chú ý tới chiến tích chấn động này."},{"chuong":645,"tieuDe":"Chương 645","tomTat":"Bên ngoài bí cảnh, Tử Tiêu Khôn vì không chịu nổi nỗi nhục thất bại trước Thạch Hạo nên kiên quyết đòi quay lại, dù lão tổ Tử Mông khẳng định hắn chưa phải đối thủ. Bất Lão Thiên tôn đề nghị cấp thêm mệnh phù răng thú nhưng Tử Mông từ chối vì trái quy củ, còn Tần Trường Sinh ngỏ ý đưa Tử Tiêu Khôn tới khu vực của Tần tộc. Cô gái Long tước vì bị thương nặng và sợ Thạch Hạo nên từ bỏ việc trở lại bí cảnh. Ở bên trong, Thạch Hạo dùng Trùng đồng thượng cổ truy tìm Ngân long liên, lần theo một dòng sông ngầm dài hàng trăm dặm tới hồ nước lớn nằm dưới chiến trường hỗn loạn. Hắn phát hiện Nguyệt Thiền đang ẩn mình dưới nước, giam chân nàng rồi đoạt hai cây Ngân long liên. Nguyệt Thiền dùng phần hồn lực vừa thức tỉnh tập kích khiến hắn suýt bất tỉnh, nhưng động thiên duy nhất đã làm suy yếu đòn thần thức. Sau khi chống đỡ thành công, Thạch Hạo xác định đây là quyết chiến sinh tử và dùng chưởng đao phù văn phản kích nàng."},{"chuong":646,"tieuDe":"Thiên Thiền Y","tomTat":"Thạch Hạo giao chiến với chủ thân Nguyệt Thiền và phát hiện lớp giáp trong suốt hòa vào huyết nhục của nàng chính là Thiên Thiền Y, một bí bảo có sức phòng ngự cực mạnh. Động thiên duy nhất của hắn giam cầm thần kiếm, làm suy yếu cốt văn và ngăn cản lực thần hồn hóa binh của Nguyệt Thiền. Không thể phá bảo y bằng sức mạnh thân thể, Thạch Hạo dùng chất lỏng chứa lôi đình cùng nguyền rủa tấn công qua những phần cơ thể không được giáp che kín, buộc nàng thu hồi hồn ảnh. Hắn nhân cơ hội giật một mảnh Thiên Thiền Y khỏi đùi nàng, để mảnh giáp lan rộng thành lớp bảo hộ cho chân trái của mình. Sau đó Thạch Hạo đuổi theo ánh bạc dưới hồ và thu được Ngân Long Liên, thánh dược dùng làm chủ dược luyện Thần Hỏa Đan. Nguyệt Thiền truy sát hắn rồi công khai việc hắn có Ngân Long Liên, còn hắn đáp trả bằng cách tiết lộ Thiên Thiền Y của nàng, khiến các cường giả xung quanh đồng loạt lao tới tranh đoạt."},{"chuong":647,"tieuDe":"Tổ Tôn Gặp Lại","tomTat":"Thạch Hạo bắt gặp một thanh niên khả nghi đang quan sát Tần Hạo và ra tay đánh văng con gấu vàng tập kích người này. Trong lúc hắn dò hỏi lai lịch của thanh niên, Thiểm Điện Tử truy đuổi cốt phù, chủ động giáng lôi điện xuống và bị Thạch Hạo dùng quyền pháp dung hợp nhiều áo nghĩa phản kích. Qua những câu hỏi về hạ giới, Thạch tộc, Tần Hạo và Thạch Tử Lăng, Thạch Hạo xác nhận thanh niên chính là tổ phụ Thạch Trung Thiên. Hắn khôi phục dung mạo thật, phóng thích khí tức huyết thống và tự nhận mình là Hạo nhi, khiến hai ông cháu xúc động nhận lại nhau sau thời gian dài tưởng rằng đối phương đã chết. Minh Tử đến từ Minh Thổ phá ngang cuộc đoàn tụ, dùng thần kiếm đen và kiếm hải tấn công cả hai người. Thạch Hạo giao chiến với hắn hơn ba trăm hiệp, kết hợp Vạn Linh đồ cùng Nguyên Thủy Chân Giải để phá minh quang hộ thể rồi đánh chết đối phương giữa không trung. Mệnh phù sau đó tái tạo Minh Tử, nhưng hắn bị Thạch Hạo buộc rời đi và cảnh cáo rằng chân thân cũng sẽ bị giết nếu còn quay lại. Trở về bên tổ phụ, Thạch Hạo khiến Thạch Trung Thiên vừa vui mừng vừa khiếp sợ trước thực lực đủ sức đánh giết một sơ đại."},{"chuong":648,"tieuDe":"Truyền Thừa Vô Thượng","tomTat":"Tin Minh Tử bị Thạch Hạo chém trong bí cảnh khiến các sơ đại và cả những cường giả đã nhen nhóm Thần hỏa đều kinh động, còn Minh Tử trở lại tế đàn bằng thân thể thật rồi yêu cầu được tái nhập. Thạch Hạo đưa Thạch Trung Thiên rời khỏi khu vực hỗn chiến, bố trí trận pháp cách ly và chính thức nhận lại tổ phụ sau thời gian dài xa cách. Qua kiểm tra, hắn biết chân huyết Ma tôn đang rèn luyện thân thể tổ phụ nhưng cũng để lại âm khí bám xương, từng bạo động khi ông bị sát thủ Thiên quốc đánh trọng thương. Thạch Hạo vì thế thề sẽ đánh lên Thiên quốc, đồng thời dự định tìm thần nhưỡng và chuẩn bị Thần Hỏa Đan để giúp tổ phụ khôi phục. Thạch Trung Thiên truyền cho hắn diệu thuật luyện thể lĩnh ngộ từ chân huyết Ma tôn, một pháp môn bắt đầu từ cốt văn bình thường nhưng có thể thúc đẩy thân thể liên tục lột xác và tái sinh Chí tôn huyết. Hai tổ tôn sau đó đặt tờ giấy vàng vào lò luyện đan chứa thiên hà cùng đất Mộ tiên, khiến nó hấp thu khí tức Tiên đạo và hiển lộ cốt văn lôi đình có uy thế vô thượng. Họ quyết định cùng lĩnh ngộ truyền thừa cấm kỵ này rồi liên thủ đối phó các cường giả còn lại trong bí cảnh."},{"chuong":649,"tieuDe":"Tứ Tuyệt Thiên","tomTat":"Thạch Hạo và Thạch Trung Thiên cùng tham ngộ tờ giấy vàng mang thần thư Lôi đạo, dùng thiên hà trong lò luyện đan để khôi phục sự hiển hiện của kinh văn. Hai người lần lượt luyện hóa cây nấm vàng và cây nhỏ đỏ như mã não lấy từ Mộ tiên, nhờ mảnh vỡ pháp tắc cùng khí tức Tiên đạo mà ngộ pháp suốt hai ngày hai đêm. Thạch Hạo lĩnh hội lực tân sinh trong hủy diệt và bốn biến hóa Lửa, Cây, Kim loại, Nước, đạt thành tựu Lôi đạo Tứ tuyệt thiên. Thạch Trung Thiên dung hợp kinh văn với truyền thừa Thần ma, lĩnh hội quang và ám rồi hiển hóa đôi cánh lôi đình đen trắng. Cả hai nhận ra bảo thuật trên giấy vàng vẫn thiếu phần sau nhưng đánh giá nội dung hiện có là truyền thừa đại đạo chí cường. Từ manh mối về Long Ngao, di tích Lôi đạo và Thiểm Điện khuyển của Chí tôn Nguyên Thiên, họ quyết định xuất quan để tìm truyền thừa, đối đầu các sơ đại và truy tìm tờ giấy vàng khác."},{"chuong":650,"tieuDe":"Cổ Thổ Hiểm Ác","tomTat":"Thạch Hạo và Đại ma thần xuyên qua vùng núi nguy hiểm, tận mắt thấy một con cóc thần vàng nuốt các hung cầm cùng cự xà Tôn Giả cảnh và suy đoán quy tắc bí cảnh Nguyên Thiên đã biến đổi. Nhận thấy nơi đây có tài nguyên tu hành phong phú và có thể tránh sự truy sát của các Giáo chủ bên ngoài, Thạch Hạo cân nhắc ở lại tu luyện lâu dài. Hai người sau đó biết cốt phù xuất hiện trước kia là đồ giả được tung ra để kích động các sơ đại chém giết, nhưng vẫn bỏ qua cuộc tranh đoạt những khối cốt phù thật để vào cổ địa hái Kim huyết thảo. Tin chân huyết Chí Tôn xuất thế tiếp tục dẫn nhiều tu sĩ tới một hòn đảo có quang môn, song nơi này thực chất là bẫy sát trận khiến một sơ đại bị giết, một sơ đại khác trọng thương và nhiều người bên ngoài gặp nạn. Thiếu niên mặt trái táo đứng sau bố cục lấy được cốt phù của người đã ngã xuống, nhưng lập tức dùng truyền tống trận rút lui khi phát hiện Thạch Hạo cùng Đại ma thần đang ẩn nấp. Chứng kiến những âm mưu ngày càng hiểm ác, Thạch Hạo không thoái chí mà càng mong chờ cuộc tranh bá lớn giữa các sơ đại."},{"chuong":651,"tieuDe":"Cuộc Đối Diện Đỉnh Cao","tomTat":"Thạch Hạo và Thạch Trung Thiên nhận ra sơ đại Thánh Vũ tộc dùng linh thân đánh lạc hướng trong khi chân thân ẩn nấp tìm đường bỏ trốn. Đối phương tung bức tranh đại sát khí diễn hóa sao rơi và mặt trời nổ, nhưng bóng chân long từ lò luyện ba chân tự hiện ra và nuốt sạch công kích. Thạch Hạo ngưng tụ chiến mâu lôi điện, giao chiến với đôi kiếm hóa từ cánh bạc rồi xuyên thủng mi tâm sơ đại, sau đó đoạt cốt phù truyền thừa khỏi mệnh phù răng thú. Thạch Trung Thiên đồng thời tiêu diệt bộ linh thân, rồi hai ông cháu rời khu vực hỗn loạn do Chí tôn huyết giả gây ra. Bên ngoài bí cảnh, việc nhiều sơ đại mất mệnh phù gây chấn động, còn Thạch Tử Lăng nghe chiến tích của thiếu niên Ma vương thì liên tưởng tới con trưởng. Thạch Hạo quyết định chủ động săn những kẻ từng truy sát tổ phụ, trước mắt nhắm vào đôi sát thủ Thiên quốc và tạm gác Tần tộc vì Tần Hạo đang được che chở tại đó. Cuối chương, hai ông cháu chạm mặt Nguyệt Thiền cùng truyền nhân Tiên điện, khiến một cuộc đối quyết đỉnh cao có thể bùng nổ."},{"chuong":652,"tieuDe":"Quyết Đấu Truyền Nhân Của Tiên Điện","tomTat":"Đại nhân trẻ tuổi của Tiên điện vừa gặp đã dùng chiến kích hư không tấn công Thạch Hạo, khiến Đại Ma Thần định thay cháu nghênh chiến nhưng bị Thạch Hạo kiên quyết ngăn lại. Thạch Hạo dùng lò luyện đan đỡ kích đầu rồi tách nắp lò chân hoàng để chặn đòn chém ngang cổ, khiến đám đông nhất thời tưởng hắn đã bị chém đầu. Sau khi hóa giải sát chiêu, hắn chủ động áp sát và dùng nắp lò như tấm thuẫn đối công với chiến kích hơn mười chiêu. Hai bên đều bộc lộ thân thể cùng thần lực vượt xa thế hệ trẻ thông thường, còn Thạch Hạo bị tê cánh tay và nứt gan bàn tay nhưng vẫn không rơi vào thế bại. Truyền nhân Tiên điện nhìn ra Thạch Hạo đang lấy ưu thế thân thể bù cho sự thua kém về cảnh giới và pháp lực, song vẫn bình tĩnh tiếp tục cận chiến. Nguyệt Thiền cảm thấy Thạch Hạo quen thuộc nhưng chưa nhận ra thân phận của hắn, trong khi tin tức về cuộc quyết đấu nhanh chóng lan khắp bí cảnh rồi truyền ra ngoài qua tế đàn tại lối ra."},{"chuong":653,"tieuDe":"Cuộc Chiến Tiên Ma","tomTat":"Tin thiếu niên Ma vương quyết đấu với truyền nhân trẻ tuổi của Tiên điện khiến lối ra bí cảnh sôi sục, nhưng phần lớn người ngoài vẫn tin truyền nhân Tiên điện sẽ thắng khi vận dụng pháp lực và bí thuật. Trong vùng sâu bí cảnh, Thạch Hạo dùng thân lò cùng nắp lò luyện đan đối đầu chiến kích hư không suốt hơn sáu mươi chiêu. Truyền nhân Tiên điện phát động Hư Không Đại Liệt trảm, song chiến kích đâm vào lò lại khuấy động Thiên hà và giải phóng lôi đình mang khí tức Tiên đạo đánh ngược về phía hắn. Chân long mơ hồ hiện quanh thân lò luyện hóa hư không và giam cầm thần năng, khiến bí thuật không thể phá lò hoặc làm Thạch Hạo bị thương. Hai người tiếp tục áp sát đối quyền, làm bàn tay của cả hai cùng nứt vỡ và khiến truyền nhân Tiên điện lần đầu đổ máu theo lời Trần Thanh. Từ xa, Nguyệt Thiền tiên tử và Ma nữ đều cảm thấy thiếu niên Ma vương quen thuộc, trong khi tin hắn có thể đối đầu ngang ngửa với truyền nhân Tiên điện khiến các giáo chủ càng thêm kinh động."},{"chuong":654,"tieuDe":"Tiên Vương Cửu Phong","tomTat":"Sau màn đấu quyền khiến đôi bên cùng tổn thương, truyền nhân Tiên điện dùng chân huyết bạc thi triển Tiên vương Cửu phong, tạo thành lao tù phù văn mang hình dáng Cổ điện Thanh đồng để phong kín và luyện hóa Thạch Hạo. Thạch Hạo cố thủ trong Động Thiên duy nhất, lấy Nguyên Thủy Chân Giải làm chủ khi vận chuyển cốt văn và âm thầm tìm cách đoạt Tiên huyết của đối phương. Tin tức về bảo thuật vô thượng của Tiên điện khiến những người quan chiến kiêng kỵ; Thạch Trung Thiên gần như muốn cứu viện nhưng tự dằn lại, còn Ma nữ cho rằng Thạch Hạo khó thoát chết. Truyền nhân Tiên điện tiếp tục tung Trấn Ma điện hợp nhất với lao tù và phóng chiến kích hư không nhằm bắt sống đối thủ. Thạch Hạo điều khiển lò luyện đan đánh bật chiến kích, sau đó trút đất Mộ tiên cùng một phần Thiên hà ra ngoài. Đất vàng hấp thu chân huyết bạc, trong khi lôi đình và nguyền rủa bùng phát dữ dội, nhấn chìm toàn bộ chiến trường nhưng kết quả cuộc đối đầu vẫn chưa được xác định."},{"chuong":655,"tieuDe":"Hắn Là Hoang","tomTat":"Thạch Hạo mở lò luyện đan, dùng Thiên hà chứa lôi đình cùng đất Mộ tiên mang nguyền rủa để áp chế truyền nhân Tiên điện, dù bản thân cũng bị điện làm bong da và chảy máu. Truyền nhân Tiên điện vận dụng Chiến giáp Tiên vũ cùng đồng điện chống đỡ, sau đó cận chiến ngang sức với Thạch Hạo nhưng dần suy yếu vì nguyền rủa và quyết định dừng trận. Từ Thiên hà đảo Ác Ma, đất Mộ tiên và chiến lực của thiếu niên Ma vương, những người quan chiến nhận ra Thạch Hạo chính là Hoang từng lưu danh trên thần bia. Ma huyết quỷ thần thụ bất ngờ tập kích, đánh truyền nhân Tiên điện văng xa và thổ huyết, song hắn vẫn dùng đại kích cắt mở hư không trốn thoát. Thạch Hạo vì thế xếp truyền nhân Tiên điện vào nhóm đối thủ nguy hiểm nhất, rồi dùng Thiên hà mang nguyền rủa cản hậu phương và cùng Thạch Trung Thiên rút lui. Tin Hoang xuất thế cùng sự xuất hiện của Ma huyết quỷ thần thụ nhanh chóng truyền tới lối ra bí cảnh, khiến nhiều cổ giáo và đạo thống bất hủ chú ý, đồng thời đẩy Tần tộc vào tâm điểm dư luận."},{"chuong":656,"tieuDe":"Con Đường Của Chính Mình","tomTat":"Ở nơi sâu trong bí cảnh Nguyên Thiên, Thạch Hạo dùng linh tuyền chữa lành hai nắm đấm, còn Thạch Trung Thiên cảnh báo truyền nhân Tiên điện đã đạt Tôn Giả đại viên mãn và có thể bước vào Thần Hỏa cảnh. Hai ông cháu thu gom linh dược, phối hợp phương thuốc Thạch Tộc với nhiều pháp Niết bàn để luyện bảo dịch, qua đó giúp Thạch Trung Thiên khai mở tinh hoa chân huyết Ma tôn đang bị niêm phong và phục hồi sinh cơ. Sau đó, Thạch Hạo dùng cốt đỉnh cấp Thần của bộ tộc Xích Vũ Hạc để trùng tu toàn bộ cảnh giới Hóa Linh, lần lượt đi lại ba giai đoạn Thân thể thành linh, Đắp lại chân ngã và Động Thiên dưỡng linh. Từ những lần mất rồi tái sinh Chí Tôn cốt cùng chân huyết, hắn nhận ra việc chủ động lặp lại quá trình này có thể dẫn tới Niết bàn sâu hơn, nhưng nguy cơ cửu tử nhất sinh khiến hắn chỉ coi đó là phương hướng tương lai. Trong Động Thiên duy nhất, hắn đúc thần hi và hoa văn thành đỉnh, tiên kiếm, thiên tháp cùng đạo chuông, hoàn thiện một con đường riêng kết hợp sát phạt và phòng ngự. Khi đi đến cuối lần diễn hóa Hóa Linh hiện tại, pháp lực và khả năng lĩnh ngộ quy tắc của hắn tăng mạnh, đôi mắt cũng xuất hiện dấu hiệu nhìn thấu căn nguyên. Thạch Hạo vì thế nhận ra Võ đạo Thiên nhãn mà mình khát vọng có thể đã bắt đầu lộ manh mối."},{"chuong":657,"tieuDe":"Mạnh Mẽ Săn Giết","tomTat":"Thạch Hạo chạm tới manh mối mở Võ đạo Thiên nhãn rồi cùng Thạch Trung Thiên tiếp tục bế quan để tái tạo chân thân và bù đắp những thiếu hụt trong pháp tắc hạ giới. Trong lúc đó, hai ông cháu gặp Thái Âm Ngọc Thỏ đang ăn Tử kim tham vạn năm; nàng báo rằng người Tần tộc cùng một kẻ mặc chiến y Trường sinh đang muốn đối phó Hoang. Thạch Trung Thiên nhờ trùng tu mà trẻ lại và bắt đầu mọc lại cánh tay cụt, còn Thạch Hạo khắc Nguyên Thủy Chân Giải cùng Vạn Linh đồ vào huyết nhục, xương cốt để tái tạo Minh Văn cảnh. Sau khi trao đổi truyền thừa Ma thần và các bảo thuật, họ quyết định tới khu vực Tần tộc nhưng không cho Tần Hạo biết mình đã đến. Phát hiện đôi sát thủ trẻ tuổi Thiên quốc từng tham gia truy sát Thạch Trung Thiên, hai ông cháu bố trí đường truyền tống rồi hợp lực giết cả hai trong bí cảnh. Khi mệnh phù đưa đôi sát thủ về tế đàn phục sinh, Thạch Hạo lập tức truyền tống tới gần lối ra và dùng cung bắn chết họ lần thứ hai trước mặt quần hùng. Sát kiếm tìm thấy trong di vật làm lộ thân phận Thiên quốc của hai người, khiến tổ chức sát thủ nổi danh trở thành đối tượng bị săn và chịu một phen nhục nhã công khai."},{"chuong":658,"tieuDe":"Tào Vũ Sinh","tomTat":"Tuổi tác và chiến lực của Hoang khiến quần hùng chấn động, làm nhiều Giáo chủ nảy ý định chiêu mộ hắn. Thạch Hạo bình an trở về bên Thạch Trung Thiên, tuyên bố sau khi trở thành đại Thiên Thần sẽ tới Thiên quốc thanh toán, rồi cùng tổ phụ dò xét lực lượng Tần tộc đang truy tìm mình. Biết Tần Hạo muốn tự tay đánh gục Hoang nhưng chưa muốn quyết chiến với đệ đệ và còn dè chừng các cường giả cấp Thần, Thạch Hạo lặng lẽ rút đi. Hai ông cháu gặp thiếu niên mập Tào Vũ Sinh, kẻ từng bố trí sát trận cướp cốt phù của hai sơ đại và đang mang thương tích do một con thỏ trắng gây ra. Tào Vũ Sinh lấy trộm củ ấu vàng cấp thánh dược dưới hồ, chia cho Thạch Hạo một nửa rồi kéo cả hai ông cháu vào cuộc truy sát của bích giao, buộc họ phải thoát qua truyền tống trận. Sau đó con thỏ trắng xuất hiện đá Tào Vũ Sinh vì vụ Bạch ngọc tham vương, đồng thời năm cường giả Tần tộc bị kinh động và xông tới. Đúng lúc ấy, phong ấn tiên trì của chí tôn Nguyên Thiên mở ra, thu hút truyền nhân Tiên điện, Nguyệt Thiền, Đằng Nhất, Thiểm Điện Tử, Chân Cổ cùng nhiều sơ đại hội tụ để tranh truyền thừa. Khi Thạch Hạo cố ý gọi Tào Vũ Sinh là huynh đệ trước đám đông, tên mập tái mặt vì Thái dương thần đằng, Minh Tử, tử kim Chân hống và những kẻ thù cũ đều đang nhìn hắn với sát ý."},{"chuong":659,"tieuDe":"Sát Trận Trước Lúc Khai Thiên","tomTat":"Tào Vũ Sinh bị những sơ đại từng mắc sát cục của hắn nhận ra và liên tiếp truy sát, trong khi Thạch Hạo ngoài miệng nhận là huynh đệ nhưng âm thầm chặn đường chạy của tên mập. Khi Minh Tử và truyền nhân Tiên điện lần lượt thăm dò, Tào Vũ Sinh kích hoạt một góc sát trận khắc trong máu thịt, dùng kiếm khí cùng khí hỗn độn hóa giải thần quang bạc. Truyền nhân Tiên điện nhận ra đây là tàn trận của sát trận Hỗn độn mạnh thứ ba thượng giới, một trận pháp hình thành trước khai thiên và từng giết các bá chủ vô thượng, nên quyết bắt Tào Vũ Sinh để đoạt truyền thừa. Ở phía tiên trì, Xích Lăng Không cùng một cao thủ Cung Hỏa Ma chặn đường Thạch Hạo, nhưng bị lôi đình và nguyền rủa từ lò luyện đan ép lui. Người Tần tộc sau đó đối chất với Thạch Hạo về những xung đột trước đây, còn hắn công khai thân phận Hoang và tố họ từng thuê Thiên quốc săn giết người cùng huyết thống. Tần Hạo mặc chiến y Trường sinh xuất hiện, không tin lời kể rằng tổ phụ hai người từng bị Tần tộc ép gần chết tại đảo Ác Ma và vẫn quyết khiêu chiến huynh trưởng. Giữa lúc kim cương máu phong ấn Chí tôn huyết hiện lên trong tiên trì, Tần Hạo chủ động tung quyền còn Thạch Hạo dùng một tay nghênh đón, mở màn cuộc giao thủ khiến thiên địa và hư không chấn động."},{"chuong":660,"tieuDe":"Va Chạm","tomTat":"Thạch Hạo dùng thân thể đối đầu Tần Hạo đang mặc chiến y Trường sinh và vẫn không rơi xuống hạ phong sau hàng chục lần va chạm. Tần Hạo chuyển sang vận dụng sức mạnh Luân hồi từ Chí Tôn cốt, nhưng Thạch Hạo hiểu rõ chỗ thiếu khuyết của thần thông nên né khỏi phạm vi phù văn rồi áp sát phản kích. Hai cường giả Thần Hỏa cảnh của Tần tộc bất ngờ xen vào tập kích, buộc Thạch Hạo mở lò luyện đan phóng thiên hà, lôi đình và sức mạnh nguyền rủa để chống trả. Hắn đánh trọng thương cường giả mắt trắng bạc và buộc người cầm cốt kiếm màu tím phải rút lui. Khi Tần tộc và cung Hỏa Ma tiếp tục hình thành vòng vây, Thạch Hạo công kích tiên trì, khiến linh vật, thần liệu và tinh thạch chân huyết bắn ra làm mọi phe chuyển sang tranh đoạt. Một cánh cửa sáng dẫn tới nơi truyền thừa xuất hiện, Thạch Hạo cùng Đại ma thần đoạt được hai khối thần liệu và một tinh thạch chân huyết rồi xông vào bên trong."},{"chuong":661,"tieuDe":"Liên Tục Chém Sơ Đại","tomTat":"Sau một ngày một đêm hỗn chiến trong rừng đá, Thạch Hạo và Đại ma thần đều bị thương nhưng vẫn mở được đường máu tiến sâu, trong khi phù văn nơi đây áp chế tốc độ và thần lực của mọi sinh linh. Tới vực sâu cấm không, hai ông cháu bị Minh Tử cùng Chân hống Tử kim phục kích trên những cây cầu cổ mộc, buộc Thạch Hạo phải mở động thiên duy nhất và dùng pháp môn Côn Bằng để vượt qua hiểm cảnh. Việc thi triển Côn Bằng khiến thân phận Hoang của hắn bị nhận ra, vì vậy Thạch Hạo phong tỏa khu vực rồi chém chết Minh Tử và Chân hống Tử kim. Trên đường tiến tới trung tâm, hắn lần đầu dùng Luân hồi kể từ khi lên Thượng giới, làm Thái dương thần đằng lão hóa rồi chém chết đối phương và thu lấy nguyên hình thần đằng vàng. Hắn còn hạ hai sơ đại mang mệnh phù, khiến họ bị đưa ra tế đàn lối thoát nhưng vẫn giữ được tính mạng. Khi chín ngọn núi tím chứa truyền thừa Chí tôn hiện ra, Thạch Hạo tiếp tục giết sơ đại Thánh Vũ tộc và áp sát khu vực thánh sơn."},{"chuong":662,"tieuDe":"Máu Nhuộm Thánh Sơn","tomTat":"Quần hùng tiến vào khu vực chín thánh sơn màu tím và lập tức bị cuốn vào những trận chiến đẫm máu với sinh linh bản địa, khiến cả thần linh lẫn sơ đại liên tiếp thương vong. Rết tím tiêu diệt đàn quạ lửa, truyền nhân Tiên điện dùng đồng thuật và đại kích chém chết voi ma mút, còn bò cạp xanh cùng bọ ngựa ngọc bích lần lượt hạ gục hai sơ đại. Ở các chiến trường khác, Ma nữ và Hắc Lan đều bị thương, trong khi chàng trai cầm kim đăng thiêu chảy đàn bọ cánh cứng đông tới mấy vạn con. Thạch Hạo và Thạch Trung Thiên dựa vào lò luyện đan chống lại Tất Phương cùng voi vàng; voi vàng bị phá nổ đầu vòi và phải tháo chạy. Tất Phương quay lại đánh lén nhưng rơi vào bẫy, bị hai ông cháu thu vào lò và luyện thành thi thể héo khô. Sau trận chiến, họ lên đỉnh thánh sơn và tiến vào cung điện truyền thừa của chí tôn Nguyên Thiên. Những thần âm, phù văn và cảm ngộ tại đó là khảo nghiệm tuyển chọn người kế thừa, đồng thời giúp Thạch Hạo kiểm chứng con đường tái tạo cảnh giới và đạt thu hoạch lớn."},{"chuong":663,"tieuDe":"Tổn Nhân Bất Lợi Kỷ","tomTat":"Các cường giả tiến vào chín cung điện trên thánh sơn để lĩnh hội tâm đắc của Chí tôn Nguyên Thiên, còn Thạch Hạo nhanh chóng xác minh nội dung từ Bàn Huyết cảnh đến Tôn giả cảnh nhưng chưa thể tiếp nhận phần Thần Hỏa cảnh. Xích Lăng Không cùng ba cường giả Thần Hỏa cảnh của Tần tộc từ bỏ cơ duyên, kéo tới ngăn hắn tiếp tục tranh đoạt truyền thừa cao nhất, trong khi voi vàng và bọ ngựa ngọc bích từ chối tham gia vây giết. Thạch Hạo và Thạch Trung Thiên dùng lò luyện đan phá vòng vây rồi xông vào cung điện của đối phương, phóng lôi đình cùng nguyền rủa khiến những người ở đó cũng không thể tiếp tục ngộ đạo. Tần Hạo mặc chiến y Trường sinh, vận chuyển chân cốt chí tôn giao chiến với anh trai nhưng bị Thạch Hạo hóa giải Luân hồi, đánh văng và tát vào mặt. Quy tắc bảo vệ truyền thừa lập tức đưa những người gây chiến lên võ đài trên không, đồng thời dập tắt Thần hỏa để tất cả phân thắng bại ở cùng cấp độ. Khi được phép chọn thêm đối thủ trong nhóm vừa tham chiến, Thạch Hạo triển khai động thiên duy nhất giam cầm một cường giả rồi đánh nổ người này thành mưa máu."},{"chuong":664,"tieuDe":"Ma Vương Thu Hoạch","tomTat":"Thạch Hạo đánh chết một cường giả Thần Hỏa cảnh của Tần tộc trên võ đài, rồi phát hiện thi thể không được mệnh phù đưa khỏi bí cảnh và thu lấy miếng mệnh phù hình răng thú. Hắn đối chất với nhóm Tần tộc từng quấy nhiễu mình ngộ đạo, sau đó một mình đối đầu năm cao thủ Tần tộc cùng hai người của Cung Hỏa Ma trong hoàn cảnh thần hỏa của đối phương bị võ đài dập tắt. Bên ngoài bí cảnh, Tần Trường Sinh và các lão Giáo chủ bàn về cái chết thật của Minh Tử, sơ đại Thánh Vũ tộc cùng những thiên tài khác, nhưng vẫn tin Tần tộc chưa tổn thất và có cơ hội đoạt truyền thừa của Chí tôn Nguyên Thiên. Để xoa dịu các đạo thống mất hậu nhân, Tần Trường Sinh miễn cưỡng hứa sẽ chia sẻ truyền thừa cấm kỵ nếu Tần tộc thành công. Trên võ đài, Thạch Hạo dùng Động thiên duy nhất hóa giải đồng thuật không trọn vẹn, rồi vận dụng Lôi đạo tầng thứ tư tạo chiến mâu và kiếm thần để liên tiếp giết các cao thủ Tần tộc. Những người Tần tộc quan chiến kinh hãi, vội phái người báo cho Thiên tôn rằng mệnh phù đã mất hiệu lực, trong khi Tần Trường Sinh vẫn chưa biết biến cố và tiếp tục trấn giữ lối ra."},{"chuong":665,"tieuDe":"Chiến Tích Huy Hoàng","tomTat":"Bên ngoài bí cảnh, Tần Trường Sinh và các Giáo chủ lầm tưởng đội ngũ Tần tộc vẫn an toàn, bởi chưa có cao thủ nào bị mệnh phù đưa trở về. Trên võ đài, Thạch Hạo vận dụng lôi đình tầng thứ tư phá hủy hàng loạt bảo cụ, giết cao thủ Thần Hỏa cảnh của Tần tộc và xử tử kẻ giả chết từng cản mình nhận truyền thừa. Khi giao chiến với những cao thủ cuối cùng của Cung Hỏa Ma, lôi pháp của hắn hiển lộ áo nghĩa sinh mệnh, khiến cây cỏ và bảo thụ sinh trưởng giữa sức mạnh hủy diệt. Thạch Hạo phá Loạn thiên động địa, giết người thi triển rồi dùng cốt đao trắng chém nát pháp khí cấp thần và chém đầu Xích Lăng Không. Sau khi thu thi thể Xích Vũ Hạc vào túi Càn Khôn, hắn trở lại thánh sơn thứ sáu, chém hai người Tần tộc và giải vây cho Đại Ma Thần. Hai đệ tử Tần tộc được mệnh phù đưa ra ngoài báo rằng toàn bộ các đại nhân cấp thần đã bị Hoang giết, khiến Tần Trường Sinh, các Giáo chủ và đám đông kinh hãi trước chiến tích của thiếu niên Ma vương."},{"chuong":666,"tieuDe":"Viên Mãn","tomTat":"Tại lối ra bí cảnh, Tần Trường Sinh nổi giận vì nhiều thần linh Tần tộc bị giết, còn Tử Mông tuyên bố tất cả người đi ra đều phải chịu kiểm tra. Trên Thánh sơn thứ sáu, Thạch Hạo dùng cốt đao xử lý tử kim Chân Hống và Hạc lông đỏ, rồi phối hợp Thái Dương Thần Đằng cùng nhiều linh dược để nấu thành bảo dược. Thạch Hạo và Đại Ma Thần vừa luyện hóa dược lực vừa luận bàn tâm đắc của chí tôn Nguyên Thiên, trong khi Thái Âm Ngọc Thỏ bị dụ phá giới ăn thịt rồi uống say và cùng họ tranh thức ăn. Nhờ bảo dược, Thạch Hạo quay lại tái tạo Liệt Trận cảnh, khắc Vạn Linh đồ và dung hợp nhiều loại phù văn, qua đó hoàn thiện toàn bộ các đại cảnh giới cũ tới mức viên mãn. Sau năm ngày cảm ngộ, Thạch Hạo, Đại Ma Thần và Thái Âm Ngọc Thỏ trở thành số ít người vượt khảo nghiệm và được truyền tống vào cung điện cao nhất. Trong cổ điện hỗn độn, tờ giấy vàng Thạch Hạo mang theo nóng lên và phát lôi đình, giúp hắn xác định nơi đây cất giữ phần truyền thừa còn lại của một pháp thuật cấm kỵ chí cao."},{"chuong":667,"tieuDe":"Cung Điện Cao Nhất","tomTat":"Thạch Hạo, Đại Ma Thần và Thái Âm Ngọc Thỏ tiến vào cổ điện cao nhất, phát hiện Mộ binh chôn chiến y Thiên Khuyết thạch của Chí tôn Nguyên Thiên cùng chín bộ giáp cấp Thiên Thần. Các cường giả lập tức tranh đoạt, nhưng chín bộ giáp liên kết linh tính và mạnh đến mức không ai có thể hàng phục; bia bạc đồng thời tiết lộ Nguyên Thiên từng trọng thương tại Khu không người, niết bàn thất bại rồi tọa hóa. Thạch Hạo nhặt bộ giáp rỉ sét thứ mười và dùng lò luyện đan dẫn lôi đình chống truyền nhân Tiên điện cùng Thiên Hạt. Tiếng giảng kinh sau đó dẫn mọi người tới đạo đài hoàng kim, nơi họ phải lĩnh hội cổ kinh, chống áp lực và chiến đấu để leo lên nhận truyền thừa. Trong cuộc hỗn chiến, Thạch Hạo chém Hoàng kim Loan, giết Hoàng kim Tượng và sơ đại Ma Quỳ viên, đồng thời giao thủ ngắn với Chân Cổ; nhiều cường giả khác cũng quyết đấu trên đường lên đỉnh. Những người sống sót cuối cùng phát hiện cốt thư Nguyên Thiên trên bồ đoàn trung tâm và tờ giấy vàng bị đè phía dưới. Khi truyền nhân Tiên điện tuyên bố người mạnh nhất mới được lấy kinh thư, Thạch Hạo lập tức bước ra đối đầu."},{"chuong":668,"tieuDe":"Quyết Đấu Đỉnh Cao","tomTat":"Thạch Hạo đối đầu truyền nhân trẻ tuổi Tiên điện trên đạo đài hoàng kim vì quyết giành tờ giấy màu vàng kim mà hắn cảm thấy vô cùng quan trọng. Trong lúc hai người dùng lò luyện đan và đại kích khai chiến, chàng trai cầm kim đăng cùng Ma nữ tìm cách đoạt cốt thư màu xanh, kéo Nguyệt Thiền, Chân Cổ, Tào Vũ Sinh, Thiểm Điện Tử và nhiều sơ đại khác vào một cuộc hỗn chiến. Truyền nhân Tiên điện dùng Bạch Hổ tí đối đầu thân thể được Côn Bằng pháp gia trì của Thạch Hạo, khiến cả hai cùng chảy máu sau cú va chạm trực diện. Hắn tiếp tục triển khai Kỳ Lân túc, còn Thạch Hạo dùng thức mở đầu của sát thuật Chân Hoàng đã được hoàn thiện nhờ lĩnh ngộ Nguyên Thủy Chân Giải để chống đỡ. Thái Âm chỉ sau đó va chạm Thái Dương quyền, làm khí hỗn độn phát sinh và hư không nứt ra. Cuối chương, Thạch Hạo hóa ba đầu sáu tay, liên tục vung Thái Dương quyền và đánh trúng vai đối thủ; truyền nhân Tiên điện phải dùng ánh sáng Bạch Hổ tí bảo vệ cánh tay, nhưng trận chiến vẫn chưa phân thắng bại."},{"chuong":669,"tieuDe":"Bảo Thuật Tuyệt Thế","tomTat":"Truyền nhân trẻ tuổi Tiên điện hóa thành Cửu Đầu Điểu, rồi liên tiếp dùng Tán thủ Chân Long và Suất Bia Thủ để đấu thân thể với Thạch Hạo nhưng không thể giành ưu thế. Thạch Hạo vận dụng trạng thái ba đầu sáu tay và Thái Dương quyền, sau đó kết hợp Nguyên Thủy Chân Giải với áo nghĩa Hóa Linh cảnh để tạo đạo chuông hộ thể và kiếm thể công kích. Kiếm thể của hắn chém đôi cốt thuẫn do Nguyệt Thiền tiên tử đưa vào chiến trường thăm dò, còn cuộc va chạm với Suất Bia Thủ khiến cả hai đối thủ đều bị thương. Truyền nhân Tiên điện thừa nhận thân thể Thạch Hạo đã đạt Kim thân bất hoại và Đạo thể bất hủ, rồi giải phóng pháp lực Tôn giả đại viên mãn đang bị áp chế nhằm đoạt đạo thống của Chí tôn Nguyên Thiên. Hắn thi triển bí pháp cấm kỵ Nhân Tiên Ấn, nhưng Thạch Hạo dùng phù văn Luân Hồi kết hợp lôi đình để hóa giải, khiến hai loại thần thông triệt tiêu lẫn nhau. Truyền nhân Tiên điện tiếp tục gọi ra Chiến giáp Tiên Vũ, còn Thạch Hạo vẫn giữ lại thủ đoạn cấm kỵ, báo hiệu cuộc quyết chiến sẽ bước sang giai đoạn dữ dội hơn."},{"chuong":670,"tieuDe":"Chém Tiên","tomTat":"Truyền nhân Tiên điện huy động đồng điện, chiến giáp Tiên Vũ, đại kích, Nhân Tiên ấn và nhiều bảo thuật trấn giáo, định dựa vào ưu thế pháp lực để nhanh chóng giết Thạch Hạo. Thạch Hạo dùng lò luyện đan cùng chiến y rách nát đối đầu, trong khi bộ chiến y bất ngờ phun ráng lành và truyền pháp lực thần thánh, giúp hắn có lượng pháp lực sánh với Tôn giả đại viên mãn. Hắn kết hợp đỉnh văn và Động Thiên duy nhất để phòng ngự, đồng thời cô đọng Luân Hồi vào quyền phải và Côn Bằng vào quyền trái, lần lượt phá bóng Nhân tiên rồi đánh đối thủ thổ huyết. Hai người tiếp tục giao chiến đến ba nghìn hiệp, cùng chịu thương tích và tiêu hao nghiêm trọng. Trong quá trình đối chiếu trận chiến với Nguyên Thủy Chân Giải, Thạch Hạo nhận rõ hơn con đường tu hành của mình và bắt đầu kéo theo sức mạnh trời đất khi xuất quyền. Truyền nhân Tiên điện cưỡng ép chồng chất nhiều bảo thuật vượt quá cực hạn nên tổn thương nguyên khí, để Thạch Hạo chớp lấy sơ hở, đánh hắn bay lên rồi tung quyền xuyên vào mi tâm."},{"chuong":671,"tieuDe":"Ngàn Cân Treo Sợi Tóc","tomTat":"Sau hơn ba nghìn hiệp giao tranh, Thạch Hạo dùng một quyền ẩn chứa sức mạnh Côn Bằng xuyên thủng xương trán truyền nhân Tiên điện, phá vỡ thần thoại bất bại của đối thủ. Mệnh phù kịp thời bao bọc và đưa truyền nhân Tiên điện rời khỏi hoàng kim đạo đài, giúp hắn tránh chết thật sự. Khi Thạch Hạo vừa buông lỏng, Nhân Tiên ấn ở cảnh giới Siêu thoát tái ngưng tụ thành sinh vật hình người và đánh thân thể hắn gần tan rã. Thiểm Điện Tử, Thiên Hạt, Hắc Lan, Thao Thiết, Trần Thanh cùng nữ tôi tớ của truyền nhân Tiên điện lập tức thừa cơ vây giết hắn. Thạch Trung Thiên liều mình cứu viện, Thái Âm Ngọc Thỏ chặn Hắc Lan, còn Tào Vũ Sinh phát động sát trận thứ ba của Thượng giới để ngăn Thao Thiết. Cuối cùng, Nguyệt Thiền mang sát ý lao tới nhưng bị Ma nữ ngăn cản, khiến Thạch Hạo nhận ra hai người có thể đã nhìn thấu thân phận của hắn."},{"chuong":672,"tieuDe":"Không Đề","tomTat":"Thạch Hạo bị Nguyệt Thiền, Thiểm Điện Tử, người của Tiên điện và nhiều sinh linh mạnh vây giết khi thân thể đã nứt toác, còn Đại Ma Thần liều mạng đứng chắn bảo vệ cháu. Thái Âm Ngọc Thỏ và Tào Vũ Sinh nhập cuộc cứu viện, lần lượt cản Hắc Lan, Thao Thiết, Thiên Hạt và bọ ngựa xanh. Thạch Hạo trao lò luyện đan cho tổ phụ rồi cô đọng Luân hồi cùng Côn Bằng vào hai quyền, đánh trọng thương nhiều đối thủ và giết nữ hầu Tiên điện trong bí cảnh. Nguyệt Thiền lợi dụng lúc hắn kiệt quệ để dùng ngọc kiếm đâm xuyên ngực, khiến thân thể hắn tiến sát giới hạn tan vỡ. Mệnh phù răng thú kịp bao phủ và đưa Thạch Hạo tới tế đàn ngoài bí cảnh, nơi truyền nhân Tiên điện vừa tái sinh sau lần bị giết trước đó. Nữ hầu Tiên điện cũng tái hiện nhưng lập tức bị Thạch Hạo truy tới đá nổ tung ngay trên tế đàn. Thạch Hạo tiếp tục đánh úp truyền nhân Tiên điện, khiến đối phương bay khỏi tế đàn trước sự kinh hãi của các Giáo chủ và đông đảo tu sĩ ngoại giới."},{"chuong":673,"tieuDe":"Kỳ Hoa","tomTat":"Thạch Hạo tập kích phe Tiên điện tại tế đàn, đánh truyền nhân Tiên điện rơi xuống rồi biến cuộc tháo lui của mình thành màn truy sát một bại tướng. Truyền nhân Tiên điện đuổi vào bí cảnh và dùng Bạch hổ tí, Nhân tiên ấn cùng chiến giáp Tiên Vũ giao chiến với hồ lôi đình của Thạch Hạo, nhưng hai bên nhất thời không thể phân thắng bại. Trong lúc giao chiến, thân phận Hoang của Thạch Hạo bị công khai trước quần hùng, còn bộ giáp rách của hắn được xác nhận có nguồn gốc từ khu vực không người. Vì đều coi truyền thừa trong cung điện cao nhất quan trọng hơn, hai đối thủ tách nhau ra và trở lại khu vực tranh đoạt. Thạch Hạo dùng nửa củ ấu vàng để khôi phục nguyên khí sau thương thế trí mạng rồi được phép tiến vào điện phủ cao nhất. Tại đây, hắn nhặt một thanh cốt kiếm vô chủ, chém đầu Trần Thanh đang trọng thương và tuyên bố sẽ thanh toán những kẻ từng vây giết mình."},{"chuong":674,"tieuDe":"Bảo Thuật Truyền Thừa","tomTat":"Thạch Hạo trở lại đạo đài hoàng kim và phát hiện Thạch Trung Thiên bị nhiều người vây công đến trọng thương. Hắn lập tức truy sát Hắc Lan, phá thần kiếm bẩm sinh của nàng bằng Luân hồi phối hợp pháp môn Côn Bằng rồi chém đôi bản thể phong lan đen. Sau đó, Thạch Hạo cùng Thạch Trung Thiên, Tào Vũ Sinh và Thái Âm Ngọc Thỏ hợp lực vượt qua đám đông để chạm vào cốt thư màu xanh của chí tôn Nguyên Thiên. Từ cốt thư, hắn lần lượt nhận được Súc địa thành thốn và Chân long trảo, đồng thời nhận ra khí tức lôi đình Tiên đạo có thể giúp lấy tờ giấy vàng dưới bồ đoàn. Thạch Hạo vừa lĩnh ngộ vừa dùng Chân long trảo giao chiến với Thao Thiết, cuối cùng kết hợp Luân hồi và vuốt rồng để giết đối phương trong Động thiên duy nhất. Sau khi thanh toán Thao Thiết, hắn lập tức gọi đích danh Thiểm Điện Tử làm mục tiêu kế tiếp."},{"chuong":675,"tieuDe":"Chương 675","tomTat":"Thiểm Điện Tử chủ động quyết chiến sinh tử với Thạch Hạo, khiến lôi đình từ binh khí do hai bên diễn hóa tràn ngập đạo đài hoàng kim. Hắn liên tiếp dùng một trăm lẻ tám thiên long, tia chớp đen trắng và bảo thuật sơ đại trời ban, trong khi Thạch Hạo đáp trả bằng sức mạnh Thái âm, Thái dương, Luân hồi và Côn Bằng. Tờ giấy vàng dưới bồ đoàn bất ngờ hấp thu bảo thuật sơ đại, tạo sơ hở để Thạch Hạo xuyên thủng lồng ngực rồi đánh thân thể Thiểm Điện Tử chia năm xẻ bảy, nhưng cốt tháp kịp cứu hắn rời đi. Sự rung chuyển của tờ giấy vàng làm cấm chế mất ổn định và giải phong cốt thư xanh của chí tôn Nguyên Thiên. Thiên Hạt, Bọ ngựa xanh cùng các thần linh trong bí cảnh hợp lực tranh đoạt, song truyền nhân Tiên điện dùng Đại na di phù hớt lấy cốt thư giữa đường. Chàng trai Kim đăng lập tức dùng thần đăng giam phù triện, ngăn đối phương trốn thoát và mở ra cuộc giao chiến mới. Giữa lúc các bên tập trung vào cốt thư xanh, Thạch Hạo lại hướng tới tờ giấy vàng dưới bồ đoàn vì cho rằng nó quan trọng hơn đối với mình."},{"chuong":676,"tieuDe":"Tờ Giấy Vàng Thứ Hai","tomTat":"Thạch Hạo phát hiện bí vật dưới bồ đoàn trên đạo đài hoàng kim, nhưng ngay cả khi Đại Ma Thần, Thái Âm Ngọc Thỏ và Tào Vũ Sinh hợp sức, cả nhóm vẫn không thể lay chuyển nó. Trong lúc các cường giả tranh cốt thư màu xanh, Phượng Vũ bất ngờ dùng một bức tranh phá hủy Đại Na Di phù, khiến bảo thư trở thành vật vô chủ trước khi Tào Vũ Sinh đoạt được rồi chuyển sang cho Thái Âm Ngọc Thỏ. Thạch Hạo nhân cơ hội dùng lò luyện đan đổ Thiên hà lên bồ đoàn, kích thích tờ giấy vàng thứ hai bay ra và kéo quần hùng vào một cuộc hỗn chiến mới. Chủ thân Nguyệt Thiền nhận ra thân phận thật của hắn, nhưng bị lời bịa đặt về đứa con với thứ thân làm dao động rồi phải dùng Bổ Thiên Thuật đối phó phù văn Luân Hồi và rút lui. Thạch Hạo đặt tờ giấy vàng có sẵn vào lò, dùng lôi đình tạo cộng hưởng và dẫn thành công tờ giấy thứ hai vào trong. Hai tờ giấy hợp lại, hút lôi đình cùng thần lực từ Thiên hà và tiên thổ rồi phóng sấm chớp mang khí tức Tiên đạo, ép toàn bộ người tranh đoạt lùi xa. Khi tên Lôi Hoàng hiện lên, Thạch Hạo nhận ra lai lịch truyền thừa và liên hệ nó với khu vực không người, đồng thời nghi ngờ giáp trụ rách đang phát sáng trên người mình cũng bắt nguồn từ vùng cấm ấy."},{"chuong":677,"tieuDe":"Truyền Thừa Kết Thúc","tomTat":"Hai tờ giấy vàng hấp thu lôi điện trong Thiên hà, tái hiện phế tích Cung Lôi Đế và giúp Thạch Hạo biết chí tôn Nguyên Thiên từng trọng thương mang truyền thừa Lôi Đế ra khỏi Cấm khu trước khi niết bàn thất bại. Ghi chép còn hé lộ Lôi Đế có thể thuộc hàng Thập hung, Thiểm điện khuyển từng nhờ bản thượng truyền thừa mà hóa thành Long ngao, còn bộ giáp rách của Thạch Hạo cũng có nguồn gốc từ Cấm khu. Khi quần hùng đồng loạt vây công, Thạch Hạo bị đuôi Thiên Hạt xuyên qua chỗ thủng trên giáp trụ và trúng độc ở vai, nhưng hắn dùng bùn vàng phá hủy chiếc đuôi rồi cùng những người khác đánh Thiên Hạt đến hình thần đều diệt. Thái Âm Ngọc Thỏ ném cốt thư xanh cho Thạch Hạo, giúp hắn lĩnh ngộ Kim xà thối; sau đó hắn ném bảo thư ra để phân tán truy binh và cùng ông nội phá vòng vây. Biết mình đã thu được vật quý giá nhất, Thạch Hạo chủ động từ bỏ phần đạo thống còn lại, nhờ khí linh hoặc quy tắc nơi truyền thừa đưa hai ông cháu ra ngoài chín ngọn thần sơn. Ngoài quang môn, cóc vàng nuốt một con rết Thần Hỏa cảnh, còn bích giao xoắn đứt và nuốt bọ ngựa xanh đang truy kích. Cuối cùng, Ma huyết quỷ thần thụ ngăn Thạch Hạo lại để nói chuyện, tiết lộ cố hương của nó và nguồn gốc chiến y đều nằm ngoài ba ngàn châu, khiến hắn đặc biệt chú ý đến bí mật của khu vực không người."},{"chuong":678,"tieuDe":"Rời Khỏi Bí Cảnh","tomTat":"Ma huyết quỷ thần thụ bộc lộ sức mạnh áp đảo, chặt đứt giao tí của bích giao, đánh trọng thương cóc vàng và quét sạch phần lớn sinh linh truy sát quanh nơi truyền thừa. Cây già tiết lộ mình vốn là một hạt giống từ Cấm khu, từng được giáp trụ của chí tôn Nguyên Thiên che chở, nên xóa bỏ xung đột với Thạch Hạo. Nó cũng giải thích quy tắc đại kiếp định kỳ của bí cảnh, khiến Thạch Hạo và Thạch Trung Thiên từ bỏ kế hoạch lưu lại tu luyện lâu dài. Thạch Hạo dùng lò luyện đan luyện hóa một phần Thiên hà giúp cây già hóa giải nguyền rủa, rồi ba người cùng quan sát và ghi nhớ kinh văn Lôi đế trên tờ giấy vàng kim. Sau đó Thạch Hạo công khai khiêu khích các thế lực đang chờ ở lối ra, dụ một nhóm cường giả tiến vào để Ma huyết quỷ thần thụ quét ngang. Cuối cùng, cây già dẫn cả nhóm tới một đầu mối không gian bất ổn, giúp họ rời bí cảnh mà không phải đi qua vòng kiểm soát của các Giáo chủ."},{"chuong":679,"tieuDe":"Ma Châu","tomTat":"Tại lối ra bí cảnh, các Giáo chủ tức giận vì lời chế nhạo của Thạch Hạo nhưng không tin cậu vẫn còn ở bên trong, còn danh hiệu thiếu niên Ma vương Hoang nhanh chóng trở thành tâm điểm bàn luận. Ma huyết quỷ thần thụ hóa thành ông lão áo đen, bảo vệ Thạch Hạo và Thạch Trung Thiên vượt đầu mối không gian đầy loạn lưu, quang nhận quy tắc cùng tàn cốt cường giả. Trên đường, họ bắt gặp một cổ thuyền đen nhuốm máu đủ sức đe dọa cả Giáo chủ và lập tức tránh xa. Ba người tới dãy núi lửa thuộc Ma Châu, sau đó Ma huyết quỷ thần thụ rời đi, còn hai ông cháu tìm hiểu vùng đất và biết Ma Quỳ viên tọa lạc tại đại châu này. Thạch Trung Thiên ngâm mình trong dung nham để làm dịu âm khí từ chân huyết Ma tôn, rồi cùng Thạch Hạo dùng cỏ tím và trúc xanh từ Mộ tiên để bế quan lĩnh hội tờ giấy vàng kim thứ hai. Sau khi xuất quan, Thạch Hạo nắm thêm các biến hóa đại địa và quang ám của Lôi đế pháp, đồng thời đánh giá truyền thừa này có thể sánh với Côn Bằng pháp. Thạch Hạo quyết định tham gia đại chiến kỳ tài ba ngàn châu để tranh đoạt tạo hóa, còn Thạch Trung Thiên chọn ở lại dãy núi lửa Ma Châu tiếp tục ẩn cư tu hành."},{"chuong":680,"tieuDe":"Sắp Biến Thiên","tomTat":"Sau khi tạm biệt tổ phụ, Thạch Hạo rời vùng hoang vu Ma châu, vừa thực hành Súc địa thành thốn vừa tìm hiểu thịnh hội thiên tài và tạo hóa Tiên cổ. Hắn biết chỉ Tôn giả mới có thể tiến vào thế giới tạo hóa ấy, khiến nhiều thiên tài đủ sức nhóm Thần hỏa vẫn chủ động áp chế cảnh giới. Nhận ra các truyền tống trận siêu cấp tại Ma châu đang bị bí mật giám sát, hắn đổi sang đường bộ để vượt biên giới tới Thiên châu. Trên bình nguyên màu máu, hắn phản sát nhiều kẻ chặn đường và phải phối hợp Côn Bằng pháp với Súc địa thành thốn để thoát khỏi thần linh mạnh hơn. Mười hai Ma vương sau đó kích hoạt đại trận cổ phong cấm hư không, còn tin tức tại thành Tội Ác cho biết đoàn lính đánh thuê Luân hồi đã bị cuốn vào biến cố có thể dẫn tới đại chiến giữa Thiên Thần và Giáo chủ. Trong thành, Thạch Hạo dùng Trùng đồng nhìn ra chân thân của một thiếu nữ từng quen biết nhiều năm trước và nghi biến cố sắp tới có liên quan tới bộ tộc của nàng."},{"chuong":681,"tieuDe":"Lộ Trình Đáng Sợ","tomTat":"Tại thành Tội Ác, Thạch Hạo dùng Trùng đồng nhận ra thiếu nữ cải trang là Vân Hi và phát hiện nhiều cường giả đang âm thầm bảo vệ nàng, nhưng hắn không tới chào hỏi vì lo ngại thái độ của Thiên Nhân tộc. Sau khi dễ dàng trấn áp một hậu duệ lai giữa Nhân tộc và voi vàng đến gây sự, hắn nhớ lại giao tình cũ với Vân Hi cùng chiếc hoa tai mang ý nghĩa thông gia. Trước tin bình nguyên màu máu sắp xảy ra đại chiến, truyền tống và phi hành đều bị cản trở, Thạch Hạo gia nhập đoàn lính đánh thuê Cơn Lốc để tránh gây chú ý. Hắn bất ngờ phát hiện Vân Hi cũng ở trong nhóm được đoàn này bảo vệ, còn các hộ vệ của nàng đã phân tán vào nhiều đoàn khác nhằm che giấu hành tung. Khi hàng vạn sinh linh tiến vào bình nguyên, một chiến mâu bạc khổng lồ từ trời giáng xuống và tiêu diệt hơn hai nghìn người trong chớp mắt. Thiên Thần mặc chiến y bạc đứng trên đỉnh mâu, tuyên bố biến thiên bắt đầu và ép những người ẩn trong bóng tối xuất hiện. Hắn còn dùng một chỉ giết thủ lĩnh lính đánh thuê vừa lên tiếng thanh minh, cho thấy sẽ không ngần ngại tiếp tục tàn sát. Nhận thấy Vân Hi siết chặt nắm tay vì căng thẳng, Thạch Hạo hiểu rằng cuộc truy tìm rất có thể nhắm vào nhóm của nàng và bản thân đã đứng quá gần để tránh bị liên lụy."},{"chuong":682,"tieuDe":"Thiên Thần","tomTat":"Một Thiên Thần áo bạc đứng trên chiến mâu khổng lồ, vô cớ giết thủ lĩnh một đoàn lính đánh thuê rồi tiêu diệt cả đoàn cùng hơn một nghìn người được bảo vệ. Hắn phong tỏa bình nguyên màu máu, liên tiếp sát hại những người bỏ chạy và quét ánh bạc xé nát mặt đất, khiến thêm hàng vạn sinh linh tử vong. Vân Hi bị một tảng đá nhiễm thần quang đánh trọng thương, nhưng Thạch Hạo kịp đỡ lấy và dùng tinh lực giúp nàng ổn định thương thế; chứng kiến sức mạnh áp đảo ấy, hắn quyết chí phải đạt tới cảnh giới Thiên Thần. Mục tiêu thực sự của người áo bạc đã dùng kế thoát khỏi đoàn người và chạy vào dãy núi, nơi một trận đại chiến cùng cấp bùng phát, khiến hắn lập tức rời bình nguyên truy kích. Những người sống sót chia thành hơn trăm đội, trong đó khoảng một nửa tiếp tục hướng tới Thiên châu. Trên đường đi, họ bàn luận về Hoang, thiếu niên đã lưu danh trên thần bia Ma tôn, đánh bại nhiều sơ đại cùng truyền nhân Tiên điện và đang bị nhiều đại giáo truy tìm. Vân Hi vẫn tin thiếu niên bất bại năm xưa ở hạ giới đã chết, không nhận ra Hoang chính là người đang đồng hành với mình, nhưng bắt đầu tò mò và chủ động hỏi tên Thạch Hạo."},{"chuong":683,"tieuDe":"Biến Thiên","tomTat":"Thạch Hạo tự xưng là Ma Hi để tiếp tục che giấu thân phận khi đồng hành cùng Vân Hi, nhưng thần giác nhạy bén khiến nàng ngày càng cảm thấy hắn quen thuộc. Hai người tiến vào bình nguyên màu máu, tạm trú trong một tòa thành đá đỏ rồi tiếp tục hướng về Thiên châu sau khi nghe tin trận chiến giữa các Thiên Thần đã tạm kết thúc với đôi bên cùng bị thương. Trên đường đi, họ biết bình nguyên vốn là chiến trường thượng cổ, nơi tiên huyết và âm khí nuôi dưỡng Huyết Hồn thảo có khả năng tăng cường thần hồn. Một Thiên Thần ba đầu bất ngờ giáng xuống, chỉ bằng cuồng phong thần lực đã giết gần nghìn người rồi chặn đoàn lữ hành để truy tìm những người trẻ của Thiên Nhân tộc. Thạch Hạo lập tức nhận ra Vân Hi cùng đồng tộc chính là mục tiêu của nàng. Thiên Thần ba đầu tiết lộ rằng sáu Thiên Mệnh thạch từng giúp sáu thiên tài Thiên Nhân tộc tiến hóa đến cực hạn và dựng nên thời kỳ Hoàng tộc huy hoàng. Nay Thiên Nhân tộc muốn tìm lại kỳ thạch, còn các đạo thống thù địch quyết ngăn cản họ tái hiện sức mạnh ấy, tạo thành hành động biến thiên."},{"chuong":684,"tieuDe":"Chạy Trối Chết","tomTat":"Trên bình nguyên màu máu, nữ Thiên Thần ba đầu phát động sóng âm từ đầu mãng ngưu trên vai, sát hại hơn ba ngàn sinh linh và buộc Vân Hi phải kéo Thạch Hạo vào vùng phù văn bảo hộ. Nàng tuyên bố Vân Hi đã dung hợp Thiên Mệnh thạch nên phải bị giết để tinh luyện bảo vật trở lại, đồng thời tiết lộ bốn thiên tài đời này của Thiên Nhân tộc đều đang bị chặn giết. Một Thiên Thần già cầm chùy và một Thiên Thần tóc tím của Thiên Nhân tộc lần lượt nghênh chiến nữ Thiên Thần ba đầu cùng Thiên Thần áo bạc, mở ra cuộc đại chiến cấp Thiên Thần. Đoàn Vân Hi được đưa khỏi chiến trường, nhưng một Thiên Thần Thiên Nhân tộc tự bạo và cuộc truy sát sau đó khiến lực lượng hộ tống tổn thất nặng nề. Sau hai ngày, toàn bộ những người bảo vệ Vân Hi lần lượt chết trận, còn nàng bị đàn hung cầm đánh trọng thương. Thạch Hạo không bỏ mặc Vân Hi mà cõng nàng, thi triển Súc địa thành thốn chạy trốn nhiều ngày. Khi không còn đường lui và lo Thiên Thần tiếp tục đuổi tới, hắn đưa nàng xông vào chiến trường màu máu phủ đầy âm vụ để che giấu khí tức."},{"chuong":685,"tieuDe":"Thân Thể","tomTat":"Thạch Hạo cõng Vân Hi tiến vào vùng sương máu của chiến trường thượng cổ và bị một con vượn ma có thể phách cấp Thần Hỏa tập kích. Hắn dùng quyền cước đánh trọng thương đối phương, qua đó biết loài vượn ma không tu pháp lực mà chuyên luyện thân thể, có thể chống bảo cụ, phù văn và gần như miễn dịch pháp lực. Trong khi đó, đoàn lính đánh thuê Bách Cầm do Kim ô ba chân cầm đầu dùng tốc độ cùng thần thông truy dấu để tiếp tục săn đuổi Vân Hi. Khi xâm nhập lãnh địa vượn ma, đoàn Bách Cầm bị tập kích và mất mười một cường giả, gồm hai sinh linh cấp Thần, còn đàn vượn ma không tổn thất thành viên nào. Kim ô cùng Hỏa Vân tước buộc phải rút lui vì không thể khắc chế thể phách của đối phương. Sau đó, chín con vượn ma phát hiện và bao vây Thạch Hạo, khiến hắn thả Vân Hi xuống để chuẩn bị phá vòng vây bằng sức mạnh thân thể. Thay vì né tránh, Thạch Hạo quyết tìm hiểu bí mật miễn dịch pháp lực của chúng và xem đây là một con đường chí cường."},{"chuong":686,"tieuDe":"Miễn Dịch Pháp Lực","tomTat":"Thạch Hạo đưa Vân Hi vào cốt đỉnh rồi một mình huyết chiến với chín vượn ma Thần Hỏa cảnh có khả năng miễn dịch pháp lực, buộc hắn phải dựa vào thể phách, tốc độ và Súc địa thành thốn để cận chiến. Sau khi giết sáu con và khiến ba con còn lại bỏ chạy, hắn cũng trọng thương, nhưng đã hồi phục phần lớn sức chiến đấu sau hai canh giờ. Hai người tiến vào sào huyệt vượn ma và tìm thấy hơn năm mươi cây Huyết Hồn thảo, qua đó Vân Hi giải thích mối liên hệ giữa loại bảo thảo này, Kim Bồ quả và khả năng miễn dịch pháp lực. Bất chấp cảnh báo rằng phần lớn người từng bắt chước vượn ma đều chết, Thạch Hạo trực tiếp ăn hàng chục cây để tìm kiếm năng lực đặc biệt ấy. Bí lực của dược thảo thẩm thấu vào huyết nhục và xương cốt, khiến hắn phải dựng Động thiên duy nhất để phong tỏa thân thể và ngăn nguy cơ giải thể. Vân Hi tiến vào Động thiên để ngăn cản nhưng bị trói buộc, làm trạng thái che giấu mất hiệu lực và dung mạo thật cùng mái tóc tím lộ ra. Khi Thạch Hạo vô tình chạm vào vành tai nàng, cả hai cùng nhớ lại chuyện cũ tại Bách Đoạn sơn."},{"chuong":687,"tieuDe":"Tạo Hóa Nơi Chiến Trường","tomTat":"Vân Hi nhận thấy ân nhân trước mặt rất giống Thạch Hạo, nhưng Thạch Hạo tự xưng Ma Hi để che giấu việc mình còn sống và vẫn quyết định hộ tống nàng. Trên đường xuyên qua chiến trường cổ, hắn luyện hóa hơn năm mươi cây Huyết Hồn thảo, chịu dược lực dữ dội nhưng bước đầu cảm nhận được bí lực có thể liên quan tới khả năng miễn dịch pháp lực của vượn ma. Khi một bộ xương Chân Nhất cảnh xuất hiện, hắn phối hợp Súc địa thành thốn với cánh Quang Ám, đưa Vân Hi chạy xa hơn vạn dặm. Vân Hi tiết lộ rằng dung hợp Thiên Mệnh thạch có thể khiến nàng lột xác tới cấp độ tương đương sơ đại mạnh nhất, đồng thời hy vọng cổ tổ Thiên Nhân tộc sớm thức tỉnh để đảo ngược cục diện. Hai người tiến vào một chiến trường cổ rộng khoảng năm vạn dặm, nơi họ phát hiện cụm hơn hai trăm cây Huyết Hồn thảo dưới núi đá. Thạch Hạo ác chiến hơn nghìn chiêu với hai vượn ma và chịu nhiều trọng thương, nhưng nhờ Vân Hi dùng bảo kính chặn con đang tháo chạy, hắn cuối cùng giết được cả hai và giữ lại cơ duyên lớn trong chiến trường."},{"chuong":688,"tieuDe":"Thành Công","tomTat":"Thạch Hạo bất chấp nguy hiểm, liên tục luyện hóa Huyết Hồn thảo và nhiều lần rơi vào cảnh thân thể gần tan rã, thần hồn sắp bốc cháy. Nhờ cốt văn nguyên thủy, Động thiên duy nhất, pháp môn hóa thân thành đỉnh và Vạn Linh đồ, hắn sống sót qua cực hạn hai trăm cây rồi ăn sạch hơn hai trăm bảy mươi cây trong dãy dược thảo. Kết quả giúp hắn vô hiệu hoàn toàn đợt công kích pháp lực đầu tiên, dù đợt thứ hai vẫn có thể xuyên qua phòng ngự. Sau khi hoàn tất thử nghiệm, Thạch Hạo và Vân Hi tiến sâu vào chiến trường cổ nhằm kéo dài thời gian chờ cổ tổ Thiên Nhân tộc thức tỉnh. Hai ngày sau, đoàn lính đánh thuê Bách Cầm cùng một người trung niên và một thiên tài trẻ tuổi Chiến tộc tìm thấy họ. Nhận ra Vân Hi đã dung hợp Thiên Mệnh thạch, thiên tài Chiến tộc đề nghị nàng kết hôn để tránh làm suy giảm uy năng kỳ thạch khi cưỡng ép tinh luyện, nhưng bị nàng từ chối. Người trung niên ra lệnh bắt cả hai, còn Thạch Hạo quyết định dùng khả năng miễn dịch pháp lực vừa đạt được làm cơ hội tuyệt sát người Chiến tộc."},{"chuong":689,"tieuDe":"Vẫn Là Phong Cách Vô Địch","tomTat":"Thạch Hạo chế nhạo thiên tài Chiến tộc và đối đầu đội ngũ của Chiến tộc cùng đoàn lính đánh thuê Bách Cầm. Phía đối phương công khai muốn bắt sống Vân Hi, ép nàng gả vào Chiến tộc để làm nhục Thiên Nhân tộc và chiếm Thiên Mệnh thạch, khiến nàng phải nhờ Thạch Hạo giúp đỡ. Sau khi để Vân Hi lùi lại, Thạch Hạo một mình xông lên, lợi dụng trạng thái miễn dịch pháp lực và dung hợp pháp môn Côn Bằng, bảo thuật Luân hồi cùng thần thông Lôi đế để đánh chết cường giả Thần Hỏa cảnh của Chiến tộc. Trước vòng vây phù văn và thần hỏa của đàn hung cầm, hắn thiêu đốt tinh huyết, đạp thủng lưng rồi chém đầu Kim ô, đầu lĩnh đoàn Bách Cầm. Biết thời gian miễn dịch pháp lực sắp hết, Thạch Hạo không dây dưa với Hỏa Vân tước mà bắt sống thiên tài trẻ tuổi Chiến tộc và lao xuống đất. Trên đường phá vây, hắn còn dùng thần thông Lôi đế giết thêm vài Tôn giả Bách Cầm, khiến Vân Hi chấn động trước chiến lực áp đảo của hắn."},{"chuong":690,"tieuDe":"Ngươi Là Ai","tomTat":"Thạch Hạo bắt sống một thiên tài trẻ tuổi của Chiến tộc, thu thi thể Kim ô rồi đưa Vân Hi chạy khỏi sự truy kích của Hỏa Vân tước và đoàn lính đánh thuê Bách Cầm. Hắn thi triển Súc địa thành thốn để độn sâu xuống lòng đất, nhưng lực phong tỏa của chiến trường viễn cổ khiến hai người chỉ đi được khoảng tám trăm dặm trước khi phải trở lại mặt đất. Họ tạm bỏ mục tiêu tới Thiên châu, chuyển sang tiến sâu vào chiến trường để kéo dài thời gian chờ Lão Thiên Nhân thức tỉnh và cứu viện. Dưới chân một ngọn núi hoang, Thạch Hạo nướng thịt Kim ô và uy hiếp tù binh, từ đó biết thế hệ trẻ Chiến tộc có ba đại Chiến vương cùng lời đồn về một Chiến đế đời này. Trong suốt hành trình, chiến lực, khí chất và thói quen mang gia vị nấu nướng của thiếu niên khiến Vân Hi nhớ tới Thạch Hạo tại hạ giới. Nàng cuối cùng nhéo tai hắn và trực tiếp hỏi hắn là ai."},{"chuong":691,"tieuDe":"Quyến Rũ","tomTat":"Vân Hi nghi ngờ Thạch Hạo là cố nhân ở Hạ giới nên chủ động véo tai hắn, nhưng hành động này khiến nàng bị hắn ôm eo, nâng cằm và trêu ghẹo. Khi nàng dùng bảo thuật chống cự, năng lực miễn dịch pháp lực của Thạch Hạo khiến toàn bộ phù văn tiêu tán, song hắn vẫn tiếp tục giấu thân phận thật. Hai người cùng ăn cánh Kim ô, nhờ đó Thạch Hạo luyện hóa lượng lớn tinh hoa bẩm sinh để chữa thương và khôi phục trạng thái đỉnh cao. Trước khi tiến sâu vào chiến trường, hắn điểm một chỉ đánh gục cường giả trẻ tuổi của Chiến tộc đã chứng kiến cuộc đối thoại. Sau khi cân nhắc địa vị đặc biệt của Vân Hi, sự bảo vệ của Thiên Nhân tộc và nguy cơ các bí mật trên người mình bị phát hiện, Thạch Hạo quyết định chưa nhận lại cố nhân. Vân Hi mời hắn gia nhập Thiên Nhân tộc và bái một vị Thiên Thần làm thầy, nhưng hắn từ chối. Thạch Hạo tuyên bố rằng một mình hắn cũng có thể quật khởi thành Đế tộc, Hoàng tộc và cuối cùng được tôn làm Thiên đế."},{"chuong":692,"tieuDe":"Kim Bồ Quả","tomTat":"Thạch Hạo và Vân Hi tiếp tục đổi hướng trong chiến trường thời viễn cổ để tránh truy binh và những lãnh địa do sinh linh cấp Chân Thần chiếm giữ. Lần theo dược hương xuyên qua rừng đá, họ phát hiện Quả Kim Bồ sắp chín, một kỳ trân có thể tăng cường thần hồn và hỗ trợ khả năng miễn dịch pháp lực nhưng cực kỳ nguy hiểm nếu ăn trực tiếp. Kỳ quả mọc cạnh cốt sơn, nơi một Cốt thần cấp Chân Thần đang cầm đao ngủ đông dưới chân ngọn núi có hình dáng ngôi mộ lớn. Không thể trực tiếp đoạt quả, Thạch Hạo và Vân Hi bố trí trận pháp, cố ý để lại dấu vết nhằm dẫn truy binh tới phá vỡ thế phòng hộ. Hai ngày sau, Long tước dẫn Đoàn lính đánh thuê Bách Cầm tới cùng một nam và một nữ Chân Thần của Chiến tộc. Thạch Hạo lập tức kéo Vân Hi dùng Súc địa thành thốn trốn xuống lòng đất, trong khi ba Chân Thần phát hiện Quả Kim Bồ và đồng loạt ra tay chộp xuống khu vực cốt sơn."},{"chuong":693,"tieuDe":"Thiên Thần Niết Bàn","tomTat":"Long tước và hai Chân Thần Chiến tộc cùng tranh đoạt quả Kim Bồ nhưng Cốt thần chỉ chấp nhận đổi nó lấy Độ kiếp thần liên, khiến thương lượng nhanh chóng biến thành đại chiến. Trong khi bản thể ba Chân Thần vây công Cốt thần, linh thân của nữ Chân Thần dùng Gương Tuế Nguyệt lần theo dấu vết của Thạch Hạo và Vân Hi xuống dưới cốt sơn. Thạch Hạo dùng Trùng đồng phát hiện một huyết trì rộng lớn đang thai nghén sinh linh khổng lồ, đồng thời nhận ra Cốt thần chính là người bảo vệ nơi này. Hắn giấu Vân Hi vào cốt đỉnh màu tím, chờ kẻ truy đuổi tiến gần rồi dùng lôi đình khuấy động huyết trì. Tràng vực bùng phát phá nát Gương Tuế Nguyệt, đánh nữ Chân Thần trọng thương và khiến cả ba Chân Thần trên mặt đất phải từ bỏ quả Kim Bồ. Cốt thần nổi giận đánh thương Long tước rồi lao vào mộ xương kiểm tra sinh linh đang niết bàn. Lợi dụng lúc người trấn giữ rời đi, Thạch Hạo quay lại áp sát cây Kim Bồ, chuẩn bị đoạt quả thần thánh."},{"chuong":694,"tieuDe":"Không Đề","tomTat":"Thạch Hạo chui khỏi lòng đất và hái được quả Kim Bồ, nhưng linh thân của Nữ Chân Thần Chiến tộc bất ngờ đánh hắn thổ huyết rồi cướp mất bảo dược. Cốt thần xuất hiện đòi lại thần quả, khiến chân thân của hai cường giả Chiến tộc và Long tước quay lại tham chiến. Cốt thần niệm thần chú gọi pháp đao Thiên Thần từ cốt sơn, dùng binh khí này phá hủy các linh thân và chém trọng thương cả ba Chân Thần. Hắn tiếp tục truy sát, nhưng cuối cùng phải quay về vì nhiệm vụ không cho phép rời cốt sơn quá xa. Long tước chạy thoát trong tình trạng gần mất mạng, còn Nam Chân Thần Chiến tộc giả vờ kiệt sức để lừa Cốt thần rồi rời chiến trường. Nữ Chân Thần Chiến tộc mang quả Kim Bồ chạy tới một ngọn núi đá trị thương, không biết rằng Thạch Hạo vẫn âm thầm bám theo. Thạch Hạo phối hợp pháp môn Côn Bằng với Súc địa thành thốn để áp sát, sau đó dùng Luân Hồi bào mòn sinh cơ của bà. Đòn đánh chưa thể kết liễu Chân Thần đang trọng thương, nên hắn lao lên quyết giết đối phương và đoạt lại quả Kim Bồ."},{"chuong":695,"tieuDe":"Cổ Tổ","tomTat":"Thạch Hạo tận dụng thương thế của nữ Chân Thần Chiến tộc cùng khả năng miễn dịch pháp lực để áp sát, đánh tan thân thể rồi dùng lò luyện đan tiêu diệt thần hồn của bà. Vân Hi kinh hãi khi biết hắn đã giết một cường giả Chân Nhất cảnh dù bản thân còn chưa đạt Tôn giả đại viên mãn. Thạch Hạo tiếp tục lần theo Long tước đang hấp hối, đánh bại đoàn trưởng Bách Cầm và khiến nó chết trong lò luyện đan dưới nguyền rủa cùng tia chớp. Sau cái chết của hai Chân Thần và sự xuất thế của Quả Kim Bồ, hắn cùng Vân Hi rời khu vực cốt sơn để tránh vòng xoáy tranh đoạt. Hai người tiến vào chiến trường cổ lớn nhất trên bình nguyên màu máu, nơi có thể ngăn cách khí tức và làm bí bảo mất hiệu lực. Đúng lúc ấy, một luồng dao động khổng lồ phá vỡ phong ấn nơi xa, làm phù văn chiếu rọi trời đất và hiện ra bóng người ngồi xếp bằng giữa thần ma cùng tinh tú. Vân Hi nhận ra đó là một vị Chiến đế còn sống, tồn tại cấm kỵ từng sáng lập thần thoại vô thượng của Chiến tộc."},{"chuong":696,"tieuDe":"Chiến Đế","tomTat":"Chiến Đế, tồn tại vô thượng từng bị cho là đã tọa hóa, hiện pháp tướng từ Ma châu và đối diện lão Thiên Nhân vừa tái hiện giữa dị tượng chư thiên. Hai cổ tổ tranh luận về con đường tu hành, khiến tràng vực của họ va chạm và làm bình nguyên màu máu rung chuyển, nứt vỡ. Lão Thiên Nhân giải phóng thần uy, phá hủy đại trận cấm kỵ, làm mười hai thành Tội Ác sụp đổ và giết sạch mười hai Ma vương. Chiến Đế lập tức đưa chân thân tới bình nguyên, cảnh cáo sẽ tiêu diệt cường giả Thiên Nhân tộc nếu đối phương tiếp tục tàn sát. Do thọ nguyên đều không còn nhiều, hai người thống nhất chuyển trận quyết chiến tới thiên ngoại với hy vọng tìm được lĩnh ngộ mới. Trong cổ địa âm khí, Thạch Hạo trấn an Vân Hi rằng Chiến Đế sẽ ngăn lão Thiên Nhân làm bừa. Sau khi hai cổ tổ rời đi, người mặc ngân bào cầm chiến mâu khiêu chiến Thiên Nhân tộc, nữ tử cầm cốt chuông vàng bay lên đáp chiến và nhiều thế lực cùng đoàn lính đánh thuê bị cuốn vào cuộc hỗn chiến."},{"chuong":697,"tieuDe":"Huyết Địa Đại Loạn","tomTat":"Cuộc tranh đoạt Thiên Mệnh thạch phát triển thành đại chiến tộc vận giữa Thiên Nhân tộc và Chiến tộc, kéo theo minh hữu cùng nhiều đoàn lính đánh thuê tiến vào bình nguyên màu máu. Lão Thiên Nhân phá đại trận phong tỏa, giết mười hai Ma vương đã trợ giúp Chiến tộc rồi cùng Chiến đế tới thiên ngoại quyết chiến. Trong chiến trường viễn cổ, Thạch Hạo và Vân Hi chứng kiến một nhóm người thuộc Thiên Nhân tộc bị kỵ binh sát hại. Một đầu lĩnh Thần Hỏa cảnh dùng linh thân làm mồi và để chân thân thi triển bảo thuật Tỳ Hưu tập kích, nhưng bị trạng thái miễn dịch pháp lực của Thạch Hạo khắc chế; Thạch Hạo giết cả hai thân, đoạt cung và tiêu diệt đội kỵ binh. Dấu vết giao tranh khiến hai người liên tục bị truy sát, buộc họ huyết chiến qua hơn mười đội ngũ và từng trốn vào hang ổ Kim cương ma để tránh một Chân Thần. Sau đó, một tiểu vương gia Chiến tộc dùng bảo kính nhận dạng Vân Hi và điều động cao thủ bao vây. Hắn tiết lộ Chiến tộc có ba Chiến vương trong đời này, một người đang ở gần, khiến Vân Hi lo lắng còn Thạch Hạo chờ mong cuộc đối đầu."},{"chuong":698,"tieuDe":"Một Người","tomTat":"Một hậu duệ Chiến tộc dùng Ngọc Tịnh bình gần cấp Thiên Thần thu nhỏ và suýt hút Thạch Hạo vào trong, nhưng hắn dùng bùn vàng từ cấm khu làm ăn mòn phù văn rồi phá vây. Tận dụng thời gian miễn dịch pháp lực còn hiệu lực, Thạch Hạo giết lão bộc Thần Hỏa cảnh, toàn bộ toán người vây công Vân Hi và chính hậu duệ Chiến tộc, đồng thời thu chiếc bình đã hư hại. Chiến tộc sau đó ban lệnh thanh sát người ngoài tộc, còn một Chân Thần dưới quyền Chiến vương truy đuổi Thạch Hạo hơn mười vạn dặm và đánh hắn tổn thương nghiêm trọng cả thân thể, nguyên thần lẫn bản nguyên. Vân Hi trao Thiên Nhân đan, giúp hắn nối lại xương gãy và khôi phục trạng thái đỉnh cao chỉ sau nửa canh giờ. Thạch Hạo tạo linh thân mang Vân Hi cùng quả Kim Bồ đi làm mồi nhử để kéo Chân Thần rời xa Chiến vương, còn bản thể quay lại phản sát. Đối diện Chiến vương, hắn phủ nhận uy thế dựa vào huyết thống tổ tiên và tuyên bố một ngày nào đó bản thân một người sẽ tương đương cả Đế tộc lẫn Hoàng tộc, tự mình thành Đế."},{"chuong":699,"tieuDe":"Kiếp Quang Cửu Thiên","tomTat":"Chiến Thiên Ca bộc lộ khí thế Chiến vương và giao chiến với Thạch Hạo, trong khi nhịp bước cộng hưởng thiên địa của Thạch Hạo buộc các Tôn giả xung quanh phải rút xa. Chiến Thiên Ca dùng Chiến bia ấn kéo dài thời gian miễn dịch pháp lực của đối thủ, sau đó lấy Kim cốt giản, chiến kiếm khí và Chiến ý bất diệt liên tiếp công kích. Thạch Hạo dùng kiếm ý cọng cỏ cùng Nguyên thần pháp trong bảo thuật Lôi đế phá giải các thủ đoạn này, rồi diễn hóa thế giới lôi đình từ Ngũ hành để đánh tan chín Chiến vương thân. Chiến Thiên Ca đáp trả bằng Chiến đế thủ, phá hủy nhiều cấu trúc trong thế giới lôi đình và chống lại mười vạn thần binh. Sau hơn bốn trăm hiệp, Thạch Hạo gọi bóng mờ cửu trùng thiên giao hòa, giáng Kiếp quang Cửu thiên xuyên thủng thân thể Chiến Thiên Ca. Chiến Thiên Ca cùng các Tôn giả xung quanh nhận ra đối thủ chính là Hoang. Cuối chương, Thạch Hạo ngưng tụ đao lôi đình chém qua hư không khiến máu bắn cao, nhưng kết cục sống chết của Chiến Thiên Ca chưa được xác nhận."},{"chuong":700,"tieuDe":"Hoang, Tái Hiện","tomTat":"Thạch Hạo dùng Tiểu thiên thế giới lôi đình và Kiếp quang Cửu thiên đánh tan thân thể Chiến Thiên Ca, đồng thời quét sạch các tử sĩ cùng bộ hạ Chiến tộc lao tới cứu chủ. Trong trạng thái giao hòa với thiên địa, hắn củng cố đạo cơ, hiểu sâu thêm bảo thuật Lôi đế và đột phá từ Tôn giả sơ kỳ lên trung kỳ. Trước khi Chân Thần hộ vệ kịp tới, Thạch Hạo bổ đôi đầu Chiến Thiên Ca, để máu từ thi thể tạo thành chữ Hoang rồi dùng Súc địa thành thốn kết hợp bảo thuật Lôi đình rời đi. Sau khi hội lại với Vân Hi, hắn thu hồi linh thân bị thương và vận chuyển cốt văn để khôi phục nguyên khí, còn nàng tiết lộ con đường tiến hóa của Thiên Nhân tộc cùng nguy cơ bị đoạt Thiên Mệnh thạch trong thời kỳ niết bàn. Hai người tiến vào trung tâm chiến trường cổ, nơi máu, xương, phù văn và các xích thần trật tự đứt gãy tạo thành một vùng cấm cực kỳ nguy hiểm. Thạch Hạo dùng Trùng đồng phát hiện một cô gái tuyết y đang đứng trong cấm địa, đúng lúc đại đạo và quy tắc chấn động báo hiệu trận chiến giữa Chiến đế với lão Thiên Nhân đã kết thúc."}];
